function pathToRegexp(path, keys, options) {
    options = options || {};
    keys = keys || [];
    const strict = options.strict;
    const end = options.end !== false;
    const flags = options.sensitive ? "" : "i";
    const lookahead = options.lookahead !== false;
    let extraOffset = 0;
    const keysOffset = keys.length;
    let i = 0;
    let name = 0;
    let pos = 0;
    let backtrack = "";
    let m;

    if (path instanceof RegExp) {
        while ((m = MATCHING_GROUP_REGEXP.exec(path.source))) {
            if (m[0][0] === "\\")
                continue;

            keys.push({
                name: m[1] || name++,
                optional: false,
                offset: m.index
            });
        }

        return path;
    }

    if (Array.isArray(path)) {
        path = path.map(function(value) {
            return pathToRegexp(value, keys, options).source;
        });

        return new RegExp(path.join("|"), flags);
    }

    if (typeof path !== "string") {
        throw new TypeError("path must be a string, array of strings, or regular expression");
    }

    path = path.replace(
        /\\.|(\/)?(\.)?:(\w+)(\(.*?\))?(\*)?(\?)?|[.*]|\/\(/g,
        function(match, slash, format, key, capture, star, optional, offset) {
            pos = offset + match.length;

            if (match[0] === "\\") {
                backtrack += match;
                return match;
            }

            if (match === ".") {
                backtrack += "\\.";
                extraOffset += 1;
                return "\\.";
            }

            backtrack = slash || format ? "" : path.slice(pos, offset);

            if (match === "*") {
                extraOffset += 3;
                return "(.*)";
            }

            if (match === "/(") {
                backtrack += "/";
                extraOffset += 2;
                return "/(?:";
            }

            slash = slash || "";
            format = format ? "\\." : "";
            optional = optional || "";

            capture = capture ? capture.replace(/\\.|\*/, function(m) {
                return m === "*" ? "(.*)" : m;
            }) : backtrack ? "((?:(?!/|" + backtrack + ").)+?)" : "([^/" + format + "]+?)";

            keys.push({
                name: key,
                optional: !!optional,
                offset: offset + extraOffset
            });

            const result = "(?:" + format + slash + capture + (star ? "((?:[/" + format + "].+?)?)" : "") + ")" + optional;
            extraOffset += result.length - match.length;
            return result;
        }
    );

    while ((m = MATCHING_GROUP_REGEXP.exec(path))) {
        if (m[0][0] === "\\")
            continue;

        if (keysOffset + i === keys.length || keys[keysOffset + i].offset > m.index) {
            keys.splice(keysOffset + i, 0, {
                name: name++,
                optional: false,
                offset: m.index
            });
        }

        i++;
    }

    path += strict ? "" : path[path.length - 1] === "/" ? "?" : "/?";

    if (end) {
        path += "$";
    } else if (path[path.length - 1] !== "/") {
        path += lookahead ? "(?=/|$)" : "(?:/|$)";
    }

    return new RegExp("^" + path, flags);
}

