async (req, res) => {
    const {
        filename,
        fileSize
    } = req.body;

    if (fileSize > maxFileSize) {
        log.error(`File size ${fileSize} bytes exceeds limit of ${maxFileSize} bytes`);

        return res.status(413).json({
            error: "File too large",
            limit: maxFileSize,
            limitInMB: maxFileSize / (1024 * 1024)
        });
    }

    const uploadId = Date.now().toString();
    const filePath = path.join(uploadDir, filename);

    try {
        await ensureDirectoryExists(filePath);

        uploads.set(uploadId, {
            filename,
            filePath,
            fileSize,
            bytesReceived: 0,
            writeStream: fs.createWriteStream(filePath)
        });

        log.info(`Initialized upload for ${filename} (${fileSize} bytes)`);

        res.json({
            uploadId
        });
    } catch (err) {
        log.error(`Failed to initialize upload: ${err.message}`);

        res.status(500).json({
            error: "Failed to initialize upload"
        });
    }
}

function applyInlineOneboxes(inline, ajax, opts) {
    opts = opts || {};
    const urls = Object.keys(inline).filter(url => !_cache[url]);

    urls.forEach(url => {
        _cache[url] = {};
    });

    if (urls.length === 0) {
        return;
    }

    ajax("/inline-onebox", {
        data: {
            urls,
            category_id: opts.categoryId,
            topic_id: opts.topicId
        }
    }).then(result => {
        result["inline-oneboxes"].forEach(onebox => {
            if (onebox.title) {
                _cache[onebox.url] = onebox;
                const links = inline[onebox.url] || [];

                links.forEach(link => {
                    link.innerText = onebox.title;
                    link.classList.add("inline-onebox");
                    link.classList.remove("inline-onebox-loading");
                });
            }
        });
    });
}

