        return;
    }

    const batchSize = 10;

    for (let i = 0; i < urls.length; i += batchSize) {
        const batch = urls.slice(i, i + batchSize);

        try {
            const result = await ajax("/inline-onebox", {
                data: {
                    urls: batch,
                    category_id: opts.categoryId,
                    topic_id: opts.topicId
                }
            });

            result["inline-oneboxes"].forEach(onebox => {
                if (onebox.title) {
                    _cache[onebox.url] = onebox;
                    const links = inline[onebox.url] || [];

                    links.forEach(link => {
                        link.innerText = onebox.title;
                        link.classList.add("inline-onebox");
                        link.classList.remove("inline-onebox-loading");
                    });
                }
            });
        } catch (err) {
            console.error("Inline onebox request failed", err, batch);
        }
    }
}

async function sendNotification(filename, fileSize) {
    if (!APPRISE_URL)
        return;

    try {
        const formattedSize = formatFileSize(fileSize);
        const totalStorage = formatFileSize(calculateDirectorySize(uploadDir));
        const message = APPRISE_MESSAGE.replace("{filename}", filename).replace("{size}", formattedSize).replace("{storage}", totalStorage);
        await execAsync(`apprise "${APPRISE_URL}" -b "${message}"`);

        log.info(
            `Notification sent for: ${filename} (${formattedSize}, Total storage: ${totalStorage})`
        );
    } catch (err) {
        log.error(`Failed to send notification: ${err.message}`);
    }
}

