function iterator(
    octokit: Octokit,
    route: Route | RequestInterface,
    parameters?: RequestParameters
) {
    const options = typeof route === "function" ? route.endpoint(parameters as EndpointOptions) : octokit.request.endpoint(route, parameters);
    const requestMethod = (typeof route === "function" ? route : octokit.request) as RequestInterface;
    const method = options.method;
    const headers = options.headers;
    let url = options.url;

    return {
        [Symbol.asyncIterator]: () => ({
            async next() {
                if (!url) return {
                    done: true
                };

                try {
                    const response = await requestMethod({
                        method,
                        url,
                        headers
                    });

                    const normalizedResponse = normalizePaginatedListResponse(response);
                    url = ((normalizedResponse.headers.link || "").match(/<([^>]+)>;\s*rel="next"/) || [])[1];

                    return {
                        value: normalizedResponse
                    };
                } catch (error: any) {
                    if (error.status !== 409)
                        throw error;

                    url = "";

                    return {
                        value: {
                            status: 200,
                            headers: {},
                            data: []
                        }
                    };
                }
            }
        })
    } as AsyncIterable<any>;
}

