    if (status >= 400) {
        octokitResponse.data = await getResponseData(fetchResponse);

        throw new RequestError(toErrorMessage(octokitResponse.data), status, {
            response: octokitResponse,
            request: requestOptions
        });
    }

    octokitResponse.data = parseSuccessResponseBody ? await getResponseData(fetchResponse) : fetchResponse.body;
    return octokitResponse;
}

async function fetchWrapper(requestOptions: ReturnType<EndpointInterface>): Promise<OctokitResponse<any>> {
    const fetch: typeof globalThis.fetch = requestOptions.request?.fetch || globalThis.fetch;

    if (!fetch) {
        throw new Error(
            "fetch is not set. Please pass a fetch implementation as new Octokit({ request: { fetch }}). Learn more at https://github.com/octokit/octokit.js/#fetch-missing"
        );
    }

    const log = requestOptions.request?.log || console;
    const parseSuccessResponseBody = requestOptions.request?.parseSuccessResponseBody !== false;
    const body = isPlainObject(requestOptions.body) || Array.isArray(requestOptions.body) ? JSON.stringify(requestOptions.body) : requestOptions.body;

    const requestHeaders = Object.fromEntries(
        Object.entries(requestOptions.headers).map(([name, value]) => [name, String(value)])
    );

    let fetchResponse: Response;

    try {
        fetchResponse = await fetch(requestOptions.url, {
            method: requestOptions.method,
            body,
            redirect: requestOptions.request?.redirect,
            headers: requestHeaders,
            signal: requestOptions.request?.signal,

            ...(requestOptions.body && {
                duplex: "half"
            })
        });
    } catch (error) {
        let message = "Unknown Error";

        if (error instanceof Error) {
            if (error.name === "AbortError") {
                (error as RequestError).status = 500;
                throw error;
            }

            message = error.message;

            if (error.name === "TypeError" && "cause" in error) {
                if (error.cause instanceof Error) {
                    message = error.cause.message;
                } else if (typeof error.cause === "string") {
                    message = error.cause;
                }
            }
        }

        const requestError = new RequestError(message, 500, {
            request: requestOptions
        });

        requestError.cause = error;
        throw requestError;
    }

    const status = fetchResponse.status;
    const url = fetchResponse.url;

    const responseHeaders: {
        [header: string]: string;
    } = {};

    for (const [key, value] of fetchResponse.headers) {
        responseHeaders[key] = value;
    }

    const octokitResponse: OctokitResponse<any> = {
        url,
        status,
        headers: responseHeaders,
        data: ""
    };

    if ("deprecation" in responseHeaders) {
        const matches = responseHeaders.link && responseHeaders.link.match(/<([^<>]+)>; rel="deprecation"/);
        const deprecationLink = matches && matches.pop();

        log.warn(
            `[@octokit/request] "${requestOptions.method} ${requestOptions.url}" is deprecated. It is scheduled to be removed on ${responseHeaders.sunset}${deprecationLink ? `. See ${deprecationLink}` : ""}`
        );
    }

    if (status === 204 || status === 205) {
        return octokitResponse;
    }

    if (requestOptions.method === "HEAD") {
        if (status < 400) {
            return octokitResponse;
        }

        throw new RequestError(fetchResponse.statusText, status, {
            response: octokitResponse,
            request: requestOptions
        });
    }

    if (status === 304) {
        octokitResponse.data = await getResponseData(fetchResponse);

        throw new RequestError("Not modified", status, {
            response: octokitResponse,
            request: requestOptions
        });
    }

    if (status >= 400) {
        octokitResponse.data = await getResponseData(fetchResponse);

        throw new RequestError(toErrorMessage(octokitResponse.data), status, {
            response: octokitResponse,
            request: requestOptions
        });
    }

    octokitResponse.data = parseSuccessResponseBody ? await getResponseData(fetchResponse) : fetchResponse.body;
    return octokitResponse;
}

async (funcLogger, app) => {
    const logger = funcLogger.child({
        method: "POST",
        endpoint: "/restore-post"
    });

    app.route("/restore").post(async (req, res) => {
        if (config.get("demoMode")) {
            return res.send({
                success: false,
                status: 403,
                message: "You cannot restore database in the demo mode.",
                data: {}
            });
        }

        const authToken = req.header("X-AUTH-TOKEN");
        const isAuthenticated = await verifyAuthenticated(logger, authToken);

        if (isAuthenticated === false) {
            logger.info("Not authenticated");

            return res.send({
                success: false,
                status: 403,
                message: "Please authenticate first.",
                data: {}
            });
        }

        const {
            archive
        } = req.files;

        const filepath = `/tmp/${archive.name}`;
        archive.mv(filepath);

        const result = await new Promise(resolve => {
            shell.exec(
                `${process.cwd()}/scripts/restore.sh ${config.get("mongo.host")} ${config.get("mongo.port")} ${filepath}`,
                (code, stdout, stderr) => {
                    resolve({
                        code,
                        stdout,
                        stderr
                    });
                }
            );
        });

        if (result.code !== 0) {
            slack.sendMessage(`The restore has failed.`, {
                symbol: "global"
            });

            return res.send({
                success: false,
                status: 500,
                message: "Restore failed",
                data: result
            });
        }

        return res.send({
            success: true,
            status: 200,
            message: "Restore success",
            data: result
        });
    });
}

