                            error
                        });

                        return;
                    }

                    resolve({
                        code: 0,
                        stdout,
                        stderr
                    });
                }
            );
        });

        if (result.code !== 0) {
            slack.sendMessage(`The restore has failed.`, {
                symbol: "global"
            });

            return res.send({
                success: false,
                status: 500,
                message: "Restore failed",
                data: result
            });
        }

        return res.send({
            success: true,
