private async setTopic(room: IrcRoom, topic: string): Promise<void> {
    if (this.state.status !== BridgedClientStatus.CONNECTED) {
        throw Error("unsafeClient not ready yet");
    }

    await this.joinChannel(room.channel);
    this.log.info("Setting topic to %s in channel %s", topic, room.channel);
    return this.state.client.send("TOPIC", room.channel, topic);
}

private async setTopic(room: IrcRoom, topic: string): Promise<void> {
    const sanitized_topic = topic.replace(/\n/g, " | ").replace(/\r/g, "");

    if (this.state.status !== BridgedClientStatus.CONNECTED) {
        throw Error("unsafeClient not ready yet");
    }

    await this.joinChannel(room.channel);
    this.log.info("Setting topic to %s in channel %s", sanitized_topic, room.channel);
    return this.state.client.send("TOPIC", room.channel, sanitized_topic);
}

function(app) {
    const Response = require("../lib/httpResponse.js");
    const Template = require("mongoose").model("Template");
    const acl = require("../lib/auth").acl;
    const utils = require("../lib/utils");
    const fs = require("fs");

    app.get(
        "/api/templates",
        acl.hasPermission("templates:read"),
        function(req, res) {
            Template.getAll().then(msg => Response.Ok(res, msg)).catch(err => Response.Internal(res, err));
        }
    );

    app.post(
        "/api/templates",
        acl.hasPermission("templates:create"),
        function(req, res) {
            if (!req.body.name || !req.body.file || !req.body.ext) {
                Response.BadParameters(res, "Missing required parameters: name, ext, file");
                return;
            }

            if (!utils.validFilename(req.body.name) || !utils.validFilename(req.body.ext)) {
                Response.BadParameters(res, "Bad name or ext format");
                return;
            }

            const template = {};
            template.name = req.body.name;
            template.ext = req.body.ext;

            Template.create(template).then(data => {
                const fileBuffer = Buffer.from(req.body.file, "base64");

                fs.writeFileSync(
                    `${__basedir}/../report-templates/${template.name}.${template.ext}`,
                    fileBuffer
                );

                Response.Created(res, data);
            }).catch(err => Response.Internal(res, err));
        }
    );

    app.put(
        "/api/templates/:templateId",
        acl.hasPermission("templates:update"),
        function(req, res) {
            if (req.body.name && !utils.validFilename(req.body.name)) {
                Response.BadParameters(res, "Bad name format");
                return;
            }

            if (req.body.ext && !utils.validFilename(req.body.ext)) {
                Response.BadParameters(res, "Bad name format");
                return;
            }

            const template = {};

            if (req.body.name)
                template.name = req.body.name;

            if (req.body.file && req.body.ext)
                template.ext = req.body.ext;

            Template.update(req.params.templateId, template).then(data => {
                if (!req.body.name && req.body.file && req.body.ext) {
                    var fileBuffer = Buffer.from(req.body.file, "base64");

                    try {
                        fs.unlinkSync(`${__basedir}/../report-templates/${data.name}.${data.ext || "docx"}`);
                    } catch {}

                    fs.writeFileSync(
                        `${__basedir}/../report-templates/${data.name}.${req.body.ext}`,
                        fileBuffer
                    );
                } else if (req.body.name && !req.body.file) {
                    fs.renameSync(
                        `${__basedir}/../report-templates/${data.name}.${data.ext || "docx"}`,
                        `${__basedir}/../report-templates/${req.body.name}.${data.ext || "docx"}`
                    );
                } else if (req.body.name && req.body.file && req.body.ext) {
                    var fileBuffer = Buffer.from(req.body.file, "base64");

                    try {
                        fs.unlinkSync(`${__basedir}/../report-templates/${data.name}.${data.ext || "docx"}`);
                    } catch {}

                    fs.writeFileSync(
                        `${__basedir}/../report-templates/${req.body.name}.${req.body.ext}`,
                        fileBuffer
                    );
                }

                Response.Ok(res, "Template updated successfully");
            }).catch(err => {
                if (err.code && err.code === "ENOENT")
                    Response.NotFound(res, "Template File was not Found");
                else
                    Response.Internal(res, err);
            });
        }
    );

    app.delete(
        "/api/templates/:templateId",
        acl.hasPermission("templates:delete"),
        function(req, res) {
            Template.delete(req.params.templateId).then(data => {
                fs.unlinkSync(`${__basedir}/../report-templates/${data.name}.${data.ext || "docx"}`);
                Response.Ok(res, "Template deleted successfully");
            }).catch(err => {
                if (err.code && err.code === "ENOENT")
                    Response.Ok(res, "Template File not found but deleted successfully in database");
                else
                    Response.Internal(res, err);
            });
        }
    );

    app.get(
        "/api/templates/download/:templateId",
        acl.hasPermission("templates:read"),
        function(req, res) {
            Template.getOne(req.params.templateId).then(data => {
                const file = `${__basedir}/../report-templates/${data.name}.${data.ext || "docx"}`;
                res.download(file, `${data.name}.${data.ext}`);
            }).catch(err => Response.Internal(res, err));
        }
    );
}

function(app) {
    const fs = require("fs");
    const path = require("path");
    const tar = require("tar-stream");
    const zlib = require("zlib");
    const diskusage = require("diskusage");
    const Response = require("../lib/httpResponse.js");
    const acl = require("../lib/auth.js").acl;
    const utils = require("../lib/utils");
    const backupPath = `${__basedir}/../backup`;
    const backupTmpPath = `${backupPath}/tmpBackup`;
    const restoreTmpPath = `${backupPath}/tmpRestore`;
    const STATE_IDLE = "idle";
    const STATE_BACKUP_STARTED = "backup_started";
    const STATE_DUMPING_DATABASE = "dumping_database";
    const STATE_BUILDING_DATA = "building_data";
    const STATE_ENCRYPTING_DATA = "encrypting_data";
    const STATE_BUILDING_ARCHIVE = "building_archive";
    const STATE_BACKUP_ERROR = "backup_error";
    const STATE_RESTORE_STARTED = "restore_started";
    const STATE_EXTRACTING_INFO = "extracting_info";
    const STATE_DECRYPTING_DATA = "decrypting_data";
    const STATE_EXTRACTING_DATA = "extracting_data";
    const STATE_RESTORING_DATA = "restoring_data";
    const STATE_RESTORE_ERROR = "restore_error";
    const Audit = require("mongoose").model("Audit");
    const AuditType = require("mongoose").model("AuditType");
    const Client = require("mongoose").model("Client");
    const Company = require("mongoose").model("Company");
    const CustomField = require("mongoose").model("CustomField");
    const CustomSection = require("mongoose").model("CustomSection");
    const Language = require("mongoose").model("Language");
    const Settings = require("mongoose").model("Settings");
    const Template = require("mongoose").model("Template");
    const User = require("mongoose").model("User");
    const Vulnerability = require("mongoose").model("Vulnerability");
    const VulnerabilityCategory = require("mongoose").model("VulnerabilityCategory");
    const VulnerabilityType = require("mongoose").model("VulnerabilityType");
    const VulnerabilityUpdate = require("mongoose").model("VulnerabilityUpdate");

    function getBackupState() {
        try {
            const state = fs.readFileSync(`${backupPath}/.state`, "utf8");

            if (state.split("\n").length > 1) return {
                state: state.split("\n")[0].trim(),
                message: state.split("\n").slice(1).join("\n").trim()
            };
            else return {
                state: state,
                message: ""
            };
        } catch (error) {
            if (error.code === "ENOENT") {
                fs.writeFileSync(`${backupPath}/.state`, STATE_IDLE);
                return STATE_IDLE;
            } else {
                console.log(error);
                return "error";
            }
        }
    }

    function setBackupState(state, message = null) {
        if (!fs.existsSync(backupPath))
            fs.mkdirSync(backupPath);

        if (message)
            fs.writeFileSync(`${backupPath}/.state`, state + "\n" + message);
        else
            fs.writeFileSync(`${backupPath}/.state`, state);
    }

    function readBackupInfo(file) {
        return new Promise((resolve, reject) => {
            const fileStats = fs.statSync(`${backupPath}/${file}`);
            const readStream = fs.createReadStream(`${backupPath}/${file}`);
            const extract = tar.extract();

            extract.on("entry", (header, stream, next) => {
                if (header.name === "backup.json") {
                    let jsonData = "";

                    stream.on("data", chunk => {
                        jsonData += chunk;
                    });

                    stream.on("end", () => {
                        try {
                            jsonData = JSON.parse(jsonData);
                            const keys = ["name", "date", "slug", "type", "protected", "data"];

                            if (keys.every(e => Object.keys(jsonData).includes(e))) {
                                jsonData.filename = file;
                                jsonData.size = fileStats.size;
                                resolve(jsonData);
                            } else
                                reject(new Error("Wrong backup.json structure"));
                        } catch (error) {
                            reject(new Error("Wrong JSON data in backup.json"));
                        }
                    });

                    stream.resume();
                } else {
                    stream.on("end", () => next());
                    stream.resume();
                }
            });

            extract.on("finish", () => {
                reject(new Error("No backup.json file found in archive"));
            });

            readStream.pipe(zlib.createGunzip()).on("error", err => reject(new Error("Wrong backup file"))).pipe(extract).on("error", err => reject(new Error("Wrong backup file")));
        });
    }

    function getBackupList() {
        return new Promise((resolve, reject) => {
            const filenames = fs.readdirSync(backupPath);
            const backupList = [];
            const promises = [];

            filenames.forEach(file => {
                if (file.endsWith(".tar")) {
                    promises.push(readBackupInfo(file));
                }
            });

            Promise.allSettled(promises).then(results => {
                results.forEach(e => {
                    if (e.status === "fulfilled") {
                        backupList.push(e.value);
                    }
                });

                resolve(backupList);
            });
        });
    }

    function getBackupFilename(slug) {
        return new Promise((resolve, reject) => {
            const filenames = fs.readdirSync(backupPath);
            const promises = [];

            filenames.forEach(file => {
                if (file.endsWith(".tar")) {
                    promises.push(readBackupInfo(file));
                }
            });

            Promise.allSettled(promises).then(results => {
                const result = results.find(e => e.status === "fulfilled" && e.value.slug === slug);
                resolve(result.value.filename);
            });
        });
    }

    app.get(
        "/api/backups",
        acl.hasPermission("backups:read"),
        async function(req, res) {
            const msg = await getBackupList();
            Response.Ok(res, msg);
        }
    );

    app.get(
        "/api/backups/status",
        acl.hasPermission("backups:read"),
        function(req, res) {
            const state = getBackupState();

            const response = {
                operation: "idle",
                state: state.state,
                message: state.message
            };

            if ([
                STATE_BACKUP_STARTED,
                STATE_DUMPING_DATABASE,
                STATE_BUILDING_DATA,
                STATE_ENCRYPTING_DATA,
                STATE_BUILDING_ARCHIVE
            ].includes(state.state))
                response.operation = "backup";
            else if ([
                STATE_RESTORE_STARTED,
                STATE_EXTRACTING_INFO,
                STATE_DECRYPTING_DATA,
                STATE_EXTRACTING_DATA,
                STATE_RESTORING_DATA
            ].includes(state.state))
                response.operation = "restore";
            else if ([STATE_BACKUP_ERROR, STATE_RESTORE_ERROR].includes(state.state))
                response.operation = "idle";

            Response.Ok(res, response);
        }
    );

    app.get(
        "/api/backups/download/:slug",
        acl.hasPermission("backups:read"),
        async function(req, res) {
            const filenames = fs.readdirSync(backupPath);
            let found = false;

            const {
                resolve
            } = require("path");

            const filename = await getBackupFilename(req.params.slug);

            filenames.forEach(file => {
                if (file === `${filename}`) {
                    found = true;
                    const filePath = `${backupPath}/${filename}`;
                    const fileStats = fs.statSync(filePath);
                    const fileSize = fileStats.size;
                    const fileStream = fs.createReadStream(resolve(filePath));
                    res.setHeader("Content-Length", fileSize);
                    res.setHeader("Content-Type", "application/octet-stream");
                    res.setHeader("Content-Disposition", `attachment; filename=${filename}`);
                    fileStream.pipe(res);
                }
            });

            if (!found) {
                Response.NotFound(res, "Backup File not found");
            }
        }
    );

    app.post(
        "/api/backups/upload",
        acl.hasPermission("backups:create"),
        function(req, res) {
            const fileSize = req.headers["content-length"] || 0;
            const diskUsage = diskusage.checkSync("/");
            const maxFileSize = diskUsage.available - 1024 * 1024 * 1024;

            if (fileSize > maxFileSize) {
                Response.BadParameters(res, "Backup too large. Not enough space on disk");
                return;
            }

            const multer = require("multer");

            const storage = multer.diskStorage({
                destination: (req, file, cb) => {
                    cb(null, `${backupPath}/`);
                },

                filename: (req, file, cb) => {
                    cb(null, file.originalname);
                }
            });

            const upload = multer({
                storage: storage,

                fileFilter: (req, file, cb) => {
                    if (file.mimetype === "application/x-tar" && file.originalname.endsWith(".tar"))
                        cb(null, true);
                    else if (utils.validFilename(path.basename(file.originalname))) cb({
                        fn: "BadParameters",
                        message: "Invalid characters in filename"
                    });
                    else cb({
                        fn: "BadParameters",
                        message: "Only .tar archives are allowed"
                    });
                },

                limits: {
                    fileSize: maxFileSize
                }
            }).single("file");

            upload(req, res, err => {
                if (err instanceof multer.MulterError) {
                    Response.BadParameters(res, err);
                } else if (err) {
                    Response.Internal(res, err);
                } else {
                    readBackupInfo(req.file.originalname).then(result => {
                        Response.Created(res, result);
                    }).catch(error => {
                        fs.rmSync(`${backupPath}/${req.file.originalname}`, {
                            force: true
                        });

                        Response.BadParameters(res, error.message);
                    });
                }
            });
        }
    );

    app.delete(
        "/api/backups/:slug",
        acl.hasPermission("backups:delete"),
        async function(req, res) {
            const filenames = fs.readdirSync(backupPath);
            let deleted = false;
            const filename = await getBackupFilename(req.params.slug);

            filenames.forEach(file => {
                if (file === `${filename}`) {
                    fs.rmSync(`${backupPath}/${file}`, {
                        force: true
                    });

                    deleted = true;
                }
            });

            if (deleted)
                Response.Ok(res, "Backup deleted successfully");
            else
                Response.NotFound(res, "Backup not found");
        }
    );

    app.post("/api/backups", acl.hasPermission("backups:create"), function(req, res) {
        if (![STATE_IDLE, STATE_BACKUP_ERROR, STATE_RESTORE_ERROR].includes(getBackupState().state)) {
            Response.Processing(res, "Operation already in progress");
            return;
        }

        setBackupState(STATE_BACKUP_STARTED);
        console.log("backup started");
        const date = new Date();
        const [filename] = date.toISOString().replaceAll("-", "").replaceAll(":", "").split(".");

        const allData = [
            "Audits",
            "Vulnerabilities",
            "Vulnerabilities Updates",
            "Users",
            "Clients",
            "Companies",
            "Templates",
            "Audit Types",
            "Custom Fields",
            "Custom Sections",
            "Vulnerability Types",
            "Vulnerability Categories",
            "Settings"
        ];

        const backup = {
            name: "backup",
            slug: filename,
            date: date.toISOString(),
            type: "full",
            protected: false,
            data: allData
        };

        if (req.body.data && Array.isArray(req.body.data))
            backup.data = allData.filter(e => req.body.data.includes(e));

        if (backup.data.length === 0)
            backup.data = allData;

        if (backup.data.length < allData.length)
            backup.type = "partial";

        if (req.body.name && utils.validFilename(req.body.name))
            backup.name = req.body.name;
        else backup.name = `${backup.type} - ${date.toLocaleDateString("en-us", {
    year: "numeric",
    month: "short",
    day: "2-digit"
})}`;

        if (req.body.password)
            backup.protected = true;

        const backupPromises = [Language.backup(backupTmpPath)];

        backup.data.forEach(e => {
            if (e === "Audits") {
                backupPromises.push(Audit.backup(backupTmpPath));
            }

            if (e === "Vulnerabilities") {
                backupPromises.push(Vulnerability.backup(backupTmpPath));
            }

            if (e === "Vulnerabilities Updates") {
                backupPromises.push(VulnerabilityUpdate.backup(backupTmpPath));
            }

            if (e === "Users") {
                backupPromises.push(User.backup(backupTmpPath));
            }

            if (e === "Clients") {
                backupPromises.push(Client.backup(backupTmpPath));
            }

            if (e === "Companies") {
                backupPromises.push(Company.backup(backupTmpPath));
            }

            if (e === "Templates") {
                backupPromises.push(Template.backup(backupTmpPath));
            }

            if (e === "Audit Types") {
                backupPromises.push(AuditType.backup(backupTmpPath));
            }

