                        await archive.finalize();
                        console.log("archive finale finalized");
                    }

                    outputArchive.on("close", function() {
                        console.log("archive final closed");
                        setBackupState(STATE_IDLE);

                        fs.rmSync(backupTmpPath, {
                            recursive: true,
                            force: true
