                                        {team_obj.team_alias}
                                    </SelectItem>)
                                )}
                            </Select3>
                        </Form.Item>
                        <Form.Item
                            className="mt-8"
                            label="TPM Limit (tokens per minute)"
                            name="tpm_limit"
                            help={`tpm_limit cannot exceed team tpm_limit ${keyTeam?.tpm_limit !== null && keyTeam?.tpm_limit !== undefined ? keyTeam?.tpm_limit : "unlimited"}`}
                            rules={[{
                                validator: async (_, value) => {
                                    if (value && keyTeam && keyTeam.tpm_limit !== null && value > keyTeam.tpm_limit) {
                                        console.log(`keyTeam.tpm_limit: ${keyTeam.tpm_limit}`);
                                        throw new Error(`tpm_limit cannot exceed team max tpm_limit: $${keyTeam.tpm_limit}`);
                                    }
                                }
                            }]}>
                            <InputNumber step={1} precision={1} width={200} />
                        </Form.Item>
                        <Form.Item
                            className="mt-8"
                            label="RPM Limit (requests per minute)"
                            name="rpm_limit"
                            help={`rpm_limit cannot exceed team max tpm_limit: ${keyTeam?.rpm_limit !== null && keyTeam?.rpm_limit !== undefined ? keyTeam?.rpm_limit : "unlimited"}`}
                            rules={[{
                                validator: async (_, value) => {
                                    if (value && keyTeam && keyTeam.rpm_limit !== null && value > keyTeam.rpm_limit) {
                                        console.log(`keyTeam.rpm_limit: ${keyTeam.rpm_limit}`);
                                        throw new Error(`rpm_limit cannot exceed team max rpm_limit: $${keyTeam.rpm_limit}`);
                                    }
                                }
                            }]}>
                            <InputNumber step={1} precision={1} width={200} />
                        </Form.Item>
                    </>
                    <div
                        style={{
                            textAlign: "right",
                            marginTop: "10px"
                        }}>
                        <Button2 htmlType="submit">Edit Key</Button2>
                    </div>
                </Form>
            </Modal>)
        );
    };

    const ModelLimitModal: React.FC<ModelLimitModalProps> = (
        {
            visible,
            onCancel,
            token,
            onSubmit,
            accessToken
        }
    ) => {
        const [modelLimits, setModelLimits] = useState<{
            [key: string]: {
                tpm: number;
                rpm: number;
            };
        }>({});

        const [availableModels, setAvailableModels] = useState<string[]>([]);
        const [newModelRow, setNewModelRow] = useState<string | null>(null);

        useEffect(() => {
            if (token.metadata) {
                const tpmLimits = token.metadata.model_tpm_limit || {};
                const rpmLimits = token.metadata.model_rpm_limit || {};

                const combinedLimits: {
                    [key: string]: {
                        tpm: number;
                        rpm: number;
                    };
                } = {};

                Object.keys({
                    ...tpmLimits,
                    ...rpmLimits
                }).forEach(model => {
                    combinedLimits[model] = {
                        tpm: tpmLimits[model] || 0,
                        rpm: rpmLimits[model] || 0
                    };
                });

                setModelLimits(combinedLimits);
            }

            const fetchAvailableModels = async () => {
                try {
                    const modelDataResponse = await modelInfoCall(accessToken, "", "");
                    const allModelGroups: string[] = Array.from(new Set(modelDataResponse.data.map((model: any) => model.model_name)));
                    setAvailableModels(allModelGroups);
                } catch (error) {
                    console.error("Error fetching model data:", error);
                    message.error("Failed to fetch available models");
                }
            };

            fetchAvailableModels();
        }, [token, accessToken]);

        const handleLimitChange = (model: string, type: "tpm" | "rpm", value: number | null) => {
            setModelLimits(prev => ({
                ...prev,

                [model]: {
                    ...prev[model],
                    [type]: value || 0
                }
            }));
        };

        const handleAddLimit = () => {
            setNewModelRow("");
        };

        const handleModelSelect = (model: string) => {
            if (!modelLimits[model]) {
                setModelLimits(prev => ({
                    ...prev,

                    [model]: {
                        tpm: 0,
                        rpm: 0
                    }
                }));
            }

            setNewModelRow(null);
        };

        const handleRemoveModel = (model: string) => {
            setModelLimits(prev => {
                const {
                    [model]: _,
                    ...rest
                } = prev;

                return rest;
            });
        };

        const handleSubmit = () => {
            const updatedMetadata = {
                ...token.metadata,
                model_tpm_limit: Object.fromEntries(Object.entries(modelLimits).map(([model, limits]) => [model, limits.tpm])),
                model_rpm_limit: Object.fromEntries(Object.entries(modelLimits).map(([model, limits]) => [model, limits.rpm]))
            };

            onSubmit(updatedMetadata);
        };

        return (
            (<Modal
                title="Edit Model-Specific Limits"
                visible={visible}
                onCancel={onCancel}
                footer={null}
                width={800}>
                <div className="space-y-4">
                    <Table>
                        <TableHead>
                            <TableRow>
                                <TableHeaderCell>Model</TableHeaderCell>
                                <TableHeaderCell>TPM Limit</TableHeaderCell>
                                <TableHeaderCell>RPM Limit</TableHeaderCell>
                                <TableHeaderCell>Actions</TableHeaderCell>
                            </TableRow>
                        </TableHead>
                        <TableBody>
                            {Object.entries(modelLimits).map(([model, limits]) => (<TableRow key={model}>
                                <TableCell>{model}</TableCell>
                                <TableCell>
                                    <InputNumber
                                        value={limits.tpm}
                                        onChange={value => handleLimitChange(model, "tpm", value)} />
                                </TableCell>
                                <TableCell>
                                    <InputNumber
                                        value={limits.rpm}
                                        onChange={value => handleLimitChange(model, "rpm", value)} />
                                </TableCell>
                                <TableCell>
                                    <Button onClick={() => handleRemoveModel(model)}>Remove</Button>
                                </TableCell>
                            </TableRow>))}
                            {newModelRow !== null && (<TableRow>
                                <TableCell>
                                    <Select
                                        style={{
                                            width: 200
                                        }}
                                        placeholder="Select a model"
                                        onChange={handleModelSelect}
                                        value={newModelRow || undefined}>
                                        {availableModels.filter(m => !modelLimits.hasOwnProperty(m)).map(m => (<Option key={m} value={m}>
                                            {m}
                                        </Option>))}
                                    </Select>
                                </TableCell>
                                <TableCell>-</TableCell>
                                <TableCell>-</TableCell>
                                <TableCell>
                                    <Button onClick={() => setNewModelRow(null)}>Cancel</Button>
                                </TableCell>
                            </TableRow>)}
                        </TableBody>
                    </Table>
                    <Button onClick={handleAddLimit} disabled={newModelRow !== null}>Add Limit</Button>
                </div>
                <div className="flex justify-end space-x-4 mt-6">
                    <Button onClick={onCancel}>Cancel</Button>
                    <Button onClick={handleSubmit}>Save</Button>
                </div>
            </Modal>)
        );
    };

    const handleEditClick = (token: any) => {
        console.log("handleEditClick:", token);

        if (token.token == null) {
            if (token.token_id !== null) {
                token.token = token.token_id;
            }
        }

        let budgetDuration = null;

        if (token.budget_duration) {
            switch (token.budget_duration) {
            case "24h":
                budgetDuration = "daily";
                break;
            case "7d":
                budgetDuration = "weekly";
                break;
            case "30d":
                budgetDuration = "monthly";
                break;
            default:
                budgetDuration = "None";
            }
        }

        setSelectedToken({
            ...token,
            budget_duration: budgetDuration
        });

        setEditModalVisible(true);
    };

    const handleEditCancel = () => {
        setEditModalVisible(false);
        setSelectedToken(null);
    };

    const handleEditSubmit = async (formValues: Record<string, any>) => {
        if (accessToken == null) {
            return;
        }

        const currentKey = formValues.token;
        formValues.key = currentKey;

        if (formValues.budget_duration) {
            switch (formValues.budget_duration) {
            case "daily":
                formValues.budget_duration = "24h";
                break;
            case "weekly":
                formValues.budget_duration = "7d";
                break;
            case "monthly":
                formValues.budget_duration = "30d";
                break;
            }
        }

        console.log("handleEditSubmit:", formValues);
        const newKeyValues = await keyUpdateCall(accessToken, formValues);
        console.log("handleEditSubmit: newKeyValues", newKeyValues);

        if (data) {
            const updatedData = data.map(key => (key.token === currentKey ? newKeyValues : key));
            setData(updatedData);
        }

        message.success("Key updated successfully");
        setEditModalVisible(false);
        setSelectedToken(null);
    };

    const handleDelete = async (token: any) => {
        console.log("handleDelete:", token);

        if (token.token == null) {
            if (token.token_id !== null) {
                token.token = token.token_id;
            }
        }

        if (data == null) {
            return;
        }

        setKeyToDelete(token.token);
        localStorage.removeItem("userData" + userID);
        setIsDeleteModalOpen(true);
    };

    const confirmDelete = async () => {
        if (keyToDelete == null || data == null) {
            return;
        }

        try {
            await keyDeleteCall(accessToken, keyToDelete);
            const filteredData = data.filter(item => item.token !== keyToDelete);
            setData(filteredData);
        } catch (error) {
            console.error("Error deleting the key:", error);
        }

        setIsDeleteModalOpen(false);
        setKeyToDelete(null);
    };

    const cancelDelete = () => {
        setIsDeleteModalOpen(false);
        setKeyToDelete(null);
    };

    const handleRegenerateClick = (token: any) => {
        setSelectedToken(token);
        setNewExpiryTime(null);

        regenerateForm.setFieldsValue({
            key_alias: token.key_alias,
            max_budget: token.max_budget,
            tpm_limit: token.tpm_limit,
            rpm_limit: token.rpm_limit,
            duration: token.duration || ""
        });

        setRegenerateDialogVisible(true);
    };

    const handleRegenerateFormChange = (field: string, value: any) => {
        setRegenerateFormData((prev: any) => ({
            ...prev,
            [field]: value
        }));
    };

    const handleRegenerateKey = async () => {
        if (!premiumUser) {
            message.error(
                "Regenerate API Key is an Enterprise feature. Please upgrade to use this feature."
            );

            return;
        }

        if (selectedToken == null) {
            return;
        }

        try {
            const formValues = await regenerateForm.validateFields();
            const response = await regenerateKeyCall(accessToken, selectedToken.token, formValues);
            setRegeneratedKey(response.key);

            if (data) {
                const updatedData = data.map(item => item.token === selectedToken?.token ? {
                    ...item,
                    key_name: response.key_name,
                    ...formValues
                } : item);

                setData(updatedData);
            }

            setRegenerateDialogVisible(false);
            regenerateForm.resetFields();
            message.success("API Key regenerated successfully");
        } catch (error) {
            console.error("Error regenerating key:", error);
            message.error("Failed to regenerate API Key");
        }
    };

    if (data == null) {
        return;
    }

    console.log("RERENDER TRIGGERED");

    return (
        (<div>
            <Card
                className="w-full mx-auto flex-auto overflow-y-auto max-h-[50vh] mb-4 mt-2">
                <Table className="mt-5 max-h-[300px] min-h-[300px]">
                    <TableHead>
                        <TableRow>
                            <TableHeaderCell>Key Alias</TableHeaderCell>
                            <TableHeaderCell>Secret Key</TableHeaderCell>
                            <TableHeaderCell>Created</TableHeaderCell>
                            <TableHeaderCell>Expires</TableHeaderCell>
                            <TableHeaderCell>Spend (USD)</TableHeaderCell>
                            <TableHeaderCell>Budget (USD)</TableHeaderCell>
                            <TableHeaderCell>Budget Reset</TableHeaderCell>
                            <TableHeaderCell>Models</TableHeaderCell>
                            <TableHeaderCell>Rate Limits</TableHeaderCell>
                            <TableHeaderCell>Rate Limits per model</TableHeaderCell>
                        </TableRow>
                    </TableHead>
                    <TableBody>
                        {data.map(item => {
                            console.log(item);

                            if (item.team_id === "litellm-dashboard") {
                                return null;
                            }

                            if (selectedTeam) {
                                console.log(
                                    `item team id: ${item.team_id}, knownTeamIDs.has(item.team_id): ${knownTeamIDs.has(item.team_id)}, selectedTeam id: ${selectedTeam.team_id}`
                                );

                                if (selectedTeam.team_id == null && item.team_id !== null && !knownTeamIDs.has(item.team_id))
                                    {} else if (item.team_id != selectedTeam.team_id) {
                                    return null;
                                }

                                console.log(`item team id: ${item.team_id}, is returned`);
                            }

                            return (
                                (<TableRow key={item.token}>
                                    <TableCell
                                        style={{
                                            maxWidth: "2px",
                                            whiteSpace: "pre-wrap",
                                            overflow: "hidden"
                                        }}>
                                        {item.key_alias != null ? <Text>{item.key_alias}</Text> : <Text>Not Set</Text>}
                                    </TableCell>
                                    <TableCell>
                                        <Text>{item.key_name}</Text>
                                    </TableCell>
                                    <TableCell>
                                        {item.created_at != null ? (<div>
                                            <p
                                                style={{
                                                    fontSize: "0.70rem"
                                                }}>{new Date(item.created_at).toLocaleDateString()}</p>
                                        </div>) : (<p
                                            style={{
                                                fontSize: "0.70rem"
                                            }}>Not available</p>)}
                                    </TableCell>
                                    <TableCell>
                                        {item.expires != null ? (<div>
                                            <p
                                                style={{
                                                    fontSize: "0.70rem"
                                                }}>{new Date(item.expires).toLocaleDateString()}</p>
                                        </div>) : (<p
                                            style={{
                                                fontSize: "0.70rem"
                                            }}>Never</p>)}
                                    </TableCell>
                                    <TableCell>
                                        <Text>
                                            {(() => {
                                                try {
                                                    return parseFloat(item.spend).toFixed(4);
                                                } catch (error) {
                                                    return item.spend;
                                                }
                                            })()}
                                        </Text>
                                    </TableCell>
                                    <TableCell>
                                        {item.max_budget != null ? <Text>{item.max_budget}</Text> : <Text>Unlimited</Text>}
                                    </TableCell>
                                    <TableCell>
                                        {item.budget_reset_at != null ? (<div>
                                            <p
                                                style={{
                                                    fontSize: "0.70rem"
                                                }}>{new Date(item.budget_reset_at).toLocaleString()}</p>
                                        </div>) : (<p
                                            style={{
                                                fontSize: "0.70rem"
                                            }}>Never</p>)}
                                    </TableCell>
                                    {}
                                    {}
                                    {}
                                    <TableCell>
                                        {Array.isArray(item.models) ? (<div
                                            style={{
                                                display: "flex",
                                                flexDirection: "column"
                                            }}>
                                            {item.models.length === 0 ? (<>
                                                {selectedTeam && selectedTeam.models && selectedTeam.models.length > 0 ? (selectedTeam.models.map(
                                                    (model: string, index: number) => model === "all-proxy-models" ? (<Badge key={index} size={"xs"} className="mb-1" color="red">
                                                        <Text>All Proxy Models</Text>
                                                    </Badge>) : model === "all-team-models" ? (<Badge key={index} size={"xs"} className="mb-1" color="red">
                                                        <Text>All Team Models</Text>
                                                    </Badge>) : (<Badge key={index} size={"xs"} className="mb-1" color="blue">
                                                        <Text>{model.length > 30 ? `${model.slice(0, 30)}...` : model}</Text>
                                                    </Badge>)
                                                )) : (<Badge size={"xs"} className="mb-1" color="blue">
                                                    <Text>all-proxy-models</Text>
                                                </Badge>)}
                                            </>) : (item.models.map(
                                                (model: string, index: number) => model === "all-proxy-models" ? (<Badge key={index} size={"xs"} className="mb-1" color="red">
                                                    <Text>All Proxy Models</Text>
                                                </Badge>) : model === "all-team-models" ? (<Badge key={index} size={"xs"} className="mb-1" color="red">
                                                    <Text>All Team Models</Text>
                                                </Badge>) : (<Badge key={index} size={"xs"} className="mb-1" color="blue">
                                                    <Text>{model.length > 30 ? `${model.slice(0, 30)}...` : model}</Text>
                                                </Badge>)
                                            ))}
                                        </div>) : null}
                                    </TableCell>
                                    <TableCell>
                                        <Text>TPM:{item.tpm_limit ? item.tpm_limit : "Unlimited"} <br></br>RPM:{" "}
                                            {item.rpm_limit ? item.rpm_limit : "Unlimited"}
                                        </Text>
                                    </TableCell>
                                    <TableCell>
                                        <Button size="xs" onClick={() => handleModelLimitClick(item)}>Edit Limits</Button>
                                    </TableCell>
                                    <TableCell>
                                        <Icon
                                            onClick={() => {
                                                setSelectedToken(item);
                                                setInfoDialogVisible(true);
                                            }}
                                            icon={InformationCircleIcon}
                                            size="sm" />
                                        <Modal
                                            open={infoDialogVisible}
                                            onCancel={() => {
                                                setInfoDialogVisible(false);
                                                setSelectedToken(null);
                                            }}
                                            footer={null}
                                            width={800}>
                                            {selectedToken && (<>
                                                <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3 mt-8">
                                                    <Card>
                                                        <p
                                                            className="text-tremor-default font-medium text-tremor-content dark:text-dark-tremor-content">Spend</p>
                                                        <div className="mt-2 flex items-baseline space-x-2.5">
                                                            <p
                                                                className="text-tremor font-semibold text-tremor-content-strong dark:text-dark-tremor-content-strong">
                                                                {(() => {
                                                                    try {
                                                                        return parseFloat(selectedToken.spend).toFixed(4);
                                                                    } catch (error) {
                                                                        return selectedToken.spend;
                                                                    }
                                                                })()}
                                                            </p>
                                                        </div>
                                                    </Card>
                                                    <Card key={item.name}>
                                                        <p
                                                            className="text-tremor-default font-medium text-tremor-content dark:text-dark-tremor-content">Budget</p>
                                                        <div className="mt-2 flex items-baseline space-x-2.5">
                                                            <p
                                                                className="text-tremor font-semibold text-tremor-content-strong dark:text-dark-tremor-content-strong">
                                                                {selectedToken.max_budget != null ? (<>
                                                                    {selectedToken.max_budget}
                                                                    {selectedToken.budget_duration && (<>
                                                                        <br />Budget will be reset at{" "}
                                                                        {selectedToken.budget_reset_at ? new Date(selectedToken.budget_reset_at).toLocaleString() : "Never"}
                                                                    </>)}
                                                                </>) : (<>Unlimited</>)}
                                                            </p>
                                                        </div>
                                                    </Card>
                                                    <Card key={item.name}>
                                                        <p
                                                            className="text-tremor-default font-medium text-tremor-content dark:text-dark-tremor-content">Expires</p>
                                                        <div className="mt-2 flex items-baseline space-x-2.5">
                                                            <p
                                                                className="text-tremor-default font-small text-tremor-content-strong dark:text-dark-tremor-content-strong">
                                                                {selectedToken.expires != null ? (<>
                                                                    {new Date(selectedToken.expires).toLocaleString(undefined, {
                                                                        day: "numeric",
                                                                        month: "long",
                                                                        year: "numeric",
                                                                        hour: "numeric",
                                                                        minute: "numeric",
                                                                        second: "numeric"
                                                                    })}
                                                                </>) : (<>Never</>)}
                                                            </p>
                                                        </div>
                                                    </Card>
                                                </div>
                                                <Card className="my-4">
                                                    <Title>Token Name</Title>
                                                    <Text className="my-1">
                                                        {selectedToken.key_alias ? selectedToken.key_alias : selectedToken.key_name}
                                                    </Text>
                                                    <Title>Token ID</Title>
                                                    <Text className="my-1 text-[12px]">{selectedToken.token}</Text>
                                                    <Title>User ID</Title>
                                                    <Text className="my-1 text-[12px]">{selectedToken.user_id}</Text>
                                                    <Title>Metadata</Title>
                                                    <Text className="my-1">
                                                        <pre>{JSON.stringify(selectedToken.metadata)} </pre>
                                                    </Text>
                                                </Card>
                                                <Button
                                                    className="mx-auto flex items-center"
                                                    onClick={() => {
                                                        setInfoDialogVisible(false);
                                                        setSelectedToken(null);
                                                    }}>Close</Button>
                                            </>)}
                                        </Modal>
                                        <Icon icon={PencilAltIcon} size="sm" onClick={() => handleEditClick(item)} />
                                        <Icon onClick={() => handleRegenerateClick(item)} icon={RefreshIcon} size="sm" />
                                        <Icon onClick={() => handleDelete(item)} icon={TrashIcon} size="sm" />
                                    </TableCell>
                                </TableRow>)
                            );
                        })}
                    </TableBody>
                </Table>
                {isDeleteModalOpen && (<div className="fixed z-10 inset-0 overflow-y-auto">
                    <div
                        className="flex items-end justify-center min-h-screen pt-4 px-4 pb-20 text-center sm:block sm:p-0">
                        <div className="fixed inset-0 transition-opacity" aria-hidden="true">
                            <div className="absolute inset-0 bg-gray-500 opacity-75"></div>
                        </div>
                        {}
                        <span
                            className="hidden sm:inline-block sm:align-middle sm:h-screen"
                            aria-hidden="true">​</span>
                        {}
                        <div
                            className="inline-block align-bottom bg-white rounded-lg text-left overflow-hidden shadow-xl transform transition-all sm:my-8 sm:align-middle sm:max-w-lg sm:w-full">
                            <div className="bg-white px-4 pt-5 pb-4 sm:p-6 sm:pb-4">
                                <div className="sm:flex sm:items-start">
                                    <div className="mt-3 text-center sm:mt-0 sm:ml-4 sm:text-left">
                                        <h3 className="text-lg leading-6 font-medium text-gray-900">Delete Key</h3>
                                        <div className="mt-2">
                                            <p className="text-sm text-gray-500">Are you sure you want to delete this key ?</p>
                                        </div>
                                    </div>
                                </div>
                            </div>
                            <div className="bg-gray-50 px-4 py-3 sm:px-6 sm:flex sm:flex-row-reverse">
                                <Button onClick={confirmDelete} color="red" className="ml-2">Delete</Button>
                                <Button onClick={cancelDelete}>Cancel</Button>
                            </div>
                        </div>
                    </div>
                </div>)}
            </Card>
            {selectedToken && (<EditKeyModal
                visible={editModalVisible}
                onCancel={handleEditCancel}
                token={selectedToken}
                onSubmit={handleEditSubmit} />)}
            {selectedToken && (<ModelLimitModal
                visible={modelLimitModalVisible}
                onCancel={() => setModelLimitModalVisible(false)}
                token={selectedToken}
                onSubmit={handleModelLimitSubmit}
                accessToken={accessToken} />)}
            {}
            <Modal
                title="Regenerate API Key"
                visible={regenerateDialogVisible}
                onCancel={() => {
                    setRegenerateDialogVisible(false);
                    regenerateForm.resetFields();
                }}
                footer={[<Button
                    key="cancel"
                    onClick={() => {
                        setRegenerateDialogVisible(false);
                        regenerateForm.resetFields();
                    }}
                    className="mr-2">Cancel</Button>, <Button key="regenerate" onClick={handleRegenerateKey} disabled={!premiumUser}>
                    {premiumUser ? "Regenerate" : "Upgrade to Regenerate"}
                </Button>]}>
                {premiumUser ? (<Form
                    form={regenerateForm}
                    layout="vertical"
                    onValuesChange={(changedValues, allValues) => {
                        if ("duration" in changedValues) {
                            handleRegenerateFormChange("duration", changedValues.duration);
                        }
                    }}>
                    <Form.Item name="key_alias" label="Key Alias">
                        <TextInput disabled={true} />
                    </Form.Item>
                    <Form.Item name="max_budget" label="Max Budget (USD)">
                        <InputNumber
                            step={0.01}
                            precision={2}
                            style={{
                                width: "100%"
                            }} />
                    </Form.Item>
                    <Form.Item name="tpm_limit" label="TPM Limit">
                        <InputNumber
                            style={{
                                width: "100%"
                            }} />
                    </Form.Item>
                    <Form.Item name="rpm_limit" label="RPM Limit">
                        <InputNumber
                            style={{
                                width: "100%"
                            }} />
                    </Form.Item>
                    <Form.Item name="duration" label="Expire Key (eg: 30s, 30h, 30d)" className="mt-8">
                        <TextInput placeholder="" />
                    </Form.Item>
                    <div className="mt-2 text-sm text-gray-500">Current expiry:{" "}
                        {selectedToken?.expires != null ? new Date(selectedToken.expires).toLocaleString() : "Never"}
                    </div>
                    {newExpiryTime && <div className="mt-2 text-sm text-green-600">New expiry:{newExpiryTime}</div>}
                </Form>) : (<div>
                    <p className="mb-2 text-gray-500 italic text-[12px]">Upgrade to use this feature</p>
                    <Button variant="primary" className="mb-2">
                        <a
                            href="https://calendly.com/d/4mp-gd3-k5k/litellm-1-1-onboarding-chat"
                            target="_blank">Get Free Trial</a>
                    </Button>
                </div>)}
            </Modal>
            {}
            {regeneratedKey && (<Modal
                visible={!!regeneratedKey}
                onCancel={() => setRegeneratedKey(null)}
                footer={[<Button key="close" onClick={() => setRegeneratedKey(null)}>Close</Button>]}>
                <Grid numItems={1} className="gap-2 w-full">
                    <Title>Regenerated Key</Title>
                    <Col numColSpan={1}>
                        <p>Please replace your old key with the new key generated. For security reasons,{" "}
                            <b>you will not be able to view it again</b>through your LiteLLM account. If you lose this secret key,
                                            you will need to generate a new one.</p>
                    </Col>
                    <Col numColSpan={1}>
                        <Text className="mt-3">Key Alias:</Text>
                        <div
                            style={{
                                background: "#f8f8f8",
                                padding: "10px",
                                borderRadius: "5px",
                                marginBottom: "10px"
                            }}>
                            <pre
                                style={{
                                    wordWrap: "break-word",
                                    whiteSpace: "normal"
                                }}>
                                {selectedToken?.key_alias || "No alias set"}
                            </pre>
                        </div>
                        <Text className="mt-3">New API Key:</Text>
                        <div
                            style={{
                                background: "#f8f8f8",
                                padding: "10px",
                                borderRadius: "5px",
                                marginBottom: "10px"
                            }}>
                            <pre
                                style={{
                                    wordWrap: "break-word",
                                    whiteSpace: "normal"
                                }}>{regeneratedKey}</pre>
                        </div>
                        <CopyToClipboard
                            text={regeneratedKey}
