                            <Button className="mt-3">Copy API Key</Button>
                        </CopyToClipboard>
                    </Col>
                </Grid>
            </Modal>)}
        </div>)
    );
}

(
    {
        userID,
        userRole,
        accessToken,
        selectedTeam,
        data,
