async (
    user,
    {
        presetId,
        newPresetId,
        defaultPreset,
        ...preset
    }
) => {
    try {
        const setter = {
            $set: {}
        };

        const update = {
            presetId,
            ...preset
        };

        if (preset.tools && Array.isArray(preset.tools)) {
            update.tools = preset.tools.map(tool => tool?.pluginKey ?? tool).filter(toolName => typeof toolName === "string") ?? [];
        }

        if (newPresetId) {
            update.presetId = newPresetId;
        }

        if (defaultPreset) {
            update.defaultPreset = defaultPreset;
            update.order = 0;

            const currentDefault = await Preset.findOne({
                defaultPreset: true,
                user
            });

            if (currentDefault && currentDefault.presetId !== presetId) {
                await Preset.findByIdAndUpdate(currentDefault._id, {
                    $unset: {
                        defaultPreset: "",
                        order: ""
                    }
                });
            }
        } else if (defaultPreset === false) {
            update.defaultPreset = undefined;
            update.order = undefined;

            setter["$unset"] = {
                defaultPreset: "",
                order: ""
            };
        }

        setter.$set = update;

        return await Preset.findOneAndUpdate({
            presetId,
            user
        }, setter, {
            new: true,
            upsert: true
        });
    } catch (error) {
        logger.error("[savePreset] Error saving preset", error);

        return {
            message: "Error saving preset"
        };
    }
}

