function extract(cwd, opts) {
    if (!cwd)
        cwd = ".";

    if (!opts)
        opts = {};

    const xfs = opts.fs || fs;
    const ignore = opts.ignore || opts.filter || noop;
    const mapStream = opts.mapStream || echo;
    const own = opts.chown !== false && !win32 && processGetuid() === 0;
    const extract = opts.extract || tar.extract();
    const stack = [];
    const now = new Date();
    const umask = typeof opts.umask === "number" ? ~opts.umask : ~processUmask();
    const strict = opts.strict !== false;
    let map = opts.map || noop;
    let dmode = typeof opts.dmode === "number" ? opts.dmode : 0;
    let fmode = typeof opts.fmode === "number" ? opts.fmode : 0;

    if (opts.strip)
        map = strip(map, opts.strip);

    if (opts.readable) {
        dmode |= parseInt(555, 8);
        fmode |= parseInt(444, 8);
    }

    if (opts.writable) {
        dmode |= parseInt(333, 8);
        fmode |= parseInt(222, 8);
    }

    extract.on("entry", onentry);

    if (opts.finish)
        extract.on("finish", opts.finish);

    return extract;

    function onentry(header, stream, next) {
        header = map(header) || header;
        header.name = normalize(header.name);
        const name = path.join(cwd, path.join("/", header.name));

        if (ignore(name, header)) {
            stream.resume();
            return next();
        }

        if (header.type === "directory") {
            stack.push([name, header.mtime]);

            return mkdirfix(name, {
                fs: xfs,
                own,
                uid: header.uid,
                gid: header.gid,
                mode: header.mode
            }, stat);
        }

        const dir = path.dirname(name);

        validate(xfs, dir, path.join(cwd, "."), function(err, valid) {
            if (err)
                return next(err);

            if (!valid)
                return next(new Error(dir + " is not a valid path"));

            mkdirfix(dir, {
                fs: xfs,
                own,
                uid: header.uid,
                gid: header.gid,
                mode: 0o755
            }, function(err) {
                if (err)
                    return next(err);

                switch (header.type) {
                case "file":
                    return onfile();
                case "link":
                    return onlink();
                case "symlink":
                    return onsymlink();
                }

                if (strict)
                    return next(new Error("unsupported type for " + name + " (" + header.type + ")"));

                stream.resume();
                next();
            });
        });

        function stat(err) {
            if (err)
                return next(err);

            utimes(name, header, function(err) {
                if (err)
                    return next(err);

                if (win32)
                    return next();

                chperm(name, header, next);
            });
        }

        function onsymlink() {
            if (win32)
                return next();

            xfs.unlink(name, function() {
                xfs.symlink(header.linkname, name, stat);
            });
        }

        function onlink() {
            if (win32)
                return next();

            xfs.unlink(name, function() {
                const srcpath = path.join(cwd, path.join("/", header.linkname));

                xfs.link(srcpath, name, function(err) {
                    if (err && err.code === "EPERM" && opts.hardlinkAsFilesFallback) {
                        stream = xfs.createReadStream(srcpath);
                        return onfile();
                    }

                    stat(err);
                });
            });
        }

        function onfile() {
            const ws = xfs.createWriteStream(name);
            const rs = mapStream(stream, header);

            ws.on("error", function(err) {
                rs.destroy(err);
            });

            pump(rs, ws, function(err) {
                if (err)
                    return next(err);

                ws.on("close", stat);
            });
        }
    }

    function utimesParent(name, cb) {
        let top;

        while ((top = head(stack)) && name.slice(0, top[0].length) !== top[0])
            stack.pop();

        if (!top)
            return cb();

        xfs.utimes(top[0], now, top[1], cb);
    }

    function utimes(name, header, cb) {
        if (opts.utimes === false)
            return cb();

        if (header.type === "directory")
            return xfs.utimes(name, now, header.mtime, cb);

        if (header.type === "symlink")
            return utimesParent(name, cb);

        xfs.utimes(name, now, header.mtime, function(err) {
            if (err)
                return cb(err);

            utimesParent(name, cb);
        });
    }

    function chperm(name, header, cb) {
        const link = header.type === "symlink";
        const chmod = link ? xfs.lchmod : xfs.chmod;
        const chown = link ? xfs.lchown : xfs.chown;

        if (!chmod)
            return cb();

        const mode = (header.mode | (header.type === "directory" ? dmode : fmode)) & umask;

        if (chown && own)
            chown.call(xfs, name, header.uid, header.gid, onchown);
        else
            onchown(null);

        function onchown(err) {
            if (err)
                return cb(err);

            if (!chmod)
                return cb();

            chmod.call(xfs, name, mode, cb);
        }
    }

    function mkdirfix(name, opts, cb) {
        xfs.stat(name, function(err) {
            if (!err)
                return cb(null);

            if (err.code !== "ENOENT")
                return cb(err);

            xfs.mkdir(name, {
                mode: opts.mode,
                recursive: true
            }, function(err, made) {
                if (err)
                    return cb(err);

                chperm(name, opts, cb);
            });
        });
    }
}

function addCommands(
    app: JupyterFrontEnd,
    gitModel: GitExtension,
    fileBrowserModel: FileBrowserModel,
    settings: ISettingRegistry.ISettings,
    translator: ITranslator
): void {
    const {
        commands,
        shell,
        serviceManager
    } = app;

    const trans = translator.load("jupyterlab_git");

    commands.addCommand(CommandIDs.gitSubmitCommand, {
        label: trans.__("Commit from the Commit Box"),
        caption: trans.__("Submit the commit using the summary and description from commit box"),
        execute: () => void 0,
        isVisible: () => false
    });

    commands.addCommand(CommandIDs.gitTerminalCommand, {
        label: trans.__("Open Git Repository in Terminal"),
        caption: trans.__("Open a New Terminal to the Git Repository"),

        execute: async args => {
            const main = (await commands.execute("terminal:create-new", args)) as MainAreaWidget<ITerminal.ITerminal>;

            try {
                if (gitModel.pathRepository !== null) {
                    const terminal = main.content;

                    terminal.session.send({
                        type: "stdin",
                        content: [`cd "${gitModel.pathRepository.split("\"").join("\\\"")}"\n`]
                    });
                }

                return main;
            } catch (e) {
                console.error(e);
                main.dispose();
            }
        },

        isEnabled: () => gitModel.pathRepository !== null && app.serviceManager.terminals.isAvailable()
    });

    commands.addCommand(CommandIDs.gitUI, {
        label: trans.__("Git Interface"),
        caption: trans.__("Go to Git user interface"),

        execute: () => {
            try {
                shell.activateById("jp-git-sessions");
            } catch (err) {
                console.error("Fail to open Git tab.");
            }
        }
    });

    commands.addCommand(CommandIDs.gitInit, {
        label: trans.__("Initialize a Repository"),
        caption: trans.__("Create an empty Git repository or reinitialize an existing one"),

        execute: async () => {
