    commands.addCommand(ContextCommandIDs.gitFileDiscard, {
        label: trans.__("Discard"),

        caption: pluralizedContextLabel(
            trans.__("Discard recent changes of selected file"),
            trans.__("Discard recent changes of selected files")
        ),

        execute: async args => {
            const {
                files
            } = args as any as CommandArguments.IGitContextAction;

            const fileList = representFiles(files);

            const result = await showDialog({
                title: trans.__("Discard changes"),

                body: (<span>
                    {trans.__(
                        "Are you sure you want to permanently discard changes to the following files?               This action cannot be undone."
                    )}
                    {fileList}
                </span>),

                buttons: [Dialog.cancelButton({
                    label: trans.__("Cancel")
                }), Dialog.warnButton({
                    label: trans.__("Discard")
                })]
            });

            if (result.button.accept) {
                for (const file of files) {
                    try {
                        if (file.status === "staged" || file.status === "partially-staged") {
                            await gitModel.reset(file.to);
                        }

                        if (file.status === "unstaged" || (file.status === "partially-staged" && file.x !== "A")) {
                            await gitModel.checkout({
                                filename: file.to
                            });
                        }
                    } catch (reason) {
                        showErrorMessage(
                            trans.__("Discard changes for %1 failed.", file.to),
                            reason,
                            [Dialog.warnButton({
                                label: trans.__("Dismiss")
                            })]
                        );
                    }
                }
            }
        },

        icon: discardIcon.bindprops({
            stylesheet: "menuItem"
        })
    });

    commands.addCommand(ContextCommandIDs.gitIgnore, {
        label: pluralizedContextLabel(
            trans.__("Ignore this file (add to .gitignore)"),
            trans.__("Ignore these files (add to .gitignore)")
        ),

        caption: pluralizedContextLabel(
            trans.__("Ignore this file (add to .gitignore)"),
            trans.__("Ignore these files (add to .gitignore)")
        ),

        execute: async args => {
            const {
                files
            } = args as any as CommandArguments.IGitContextAction;

            for (const file of files) {
                if (file) {
                    await gitModel.ignore(file.to, false);
                }
            }
        }
    });

    commands.addCommand(ContextCommandIDs.gitIgnoreExtension, {
        label: args => {
            const {
                files
            } = args as any as CommandArguments.IGitContextAction;

            const extensions = files.map(file => PathExt.extname(file.to)).filter(extension => extension.length > 0).filter((item, index, arr) => arr.indexOf(item) === index);

            return trans._n(
                "Ignore %2 extension (add to .gitignore)",
                "Ignore %2 extensions (add to .gitignore)",
                extensions.length,
                extensions.join(", ")
            );
        },

        caption: pluralizedContextLabel(
            trans.__("Ignore this file extension (add to .gitignore)"),
            trans.__("Ignore these files extension (add to .gitignore)")
        ),

        execute: async args => {
            const {
                files
            } = args as any as CommandArguments.IGitContextAction;

            for (const selectedFile of files) {
                if (selectedFile) {
                    const extension = PathExt.extname(selectedFile.to);

                    if (extension.length > 0) {
                        const result = await showDialog({
                            title: trans.__("Ignore file extension"),

                            body: trans.__(
                                "Are you sure you want to ignore all %1 files within this git repository?",
                                extension
                            ),

                            buttons: [Dialog.cancelButton(), Dialog.okButton({
                                label: trans.__("Ignore")
                            })]
                        });

                        if (result.button.label === trans.__("Ignore")) {
                            await gitModel.ignore(selectedFile.to, true);
                        }
                    }
                }
            }
        },

        isVisible: args => {
            const {
                files
            } = args as any as CommandArguments.IGitContextAction;

            return files.some(selectedFile => {
                const extension = PathExt.extname(selectedFile.to);
                return extension.length > 0;
            });
        }
    });

    commands.addCommand(ContextCommandIDs.gitFileHistory, {
        label: trans.__("History"),
        caption: trans.__("View the history of this file"),

        execute: args => {
            const {
                files
            } = args as any as CommandArguments.IGitContextAction;

            const file = files[0];

            if (!file) {
                return;
            }

            gitModel.selectedHistoryFile = file;
            shell.activateById("jp-git-sessions");
        },

        isEnabled: args => {
            const {
                files
            } = args as any as CommandArguments.IGitContextAction;

            return files.length === 1;
        },

        icon: historyIcon.bindprops({
            stylesheet: "menuItem"
        })
    });

    commands.addCommand(ContextCommandIDs.gitNoAction, {
        label: trans.__("No actions available"),
        isEnabled: () => false,
        execute: () => void 0
    });
}

function addCommands(
    app: JupyterFrontEnd,
    gitModel: GitExtension,
    fileBrowserModel: FileBrowserModel,
    settings: ISettingRegistry.ISettings,
    translator: ITranslator
): void {
    const {
        commands,
        shell,
        serviceManager
    } = app;

    const trans = translator.load("jupyterlab_git");

    commands.addCommand(CommandIDs.gitSubmitCommand, {
        label: trans.__("Commit from the Commit Box"),
        caption: trans.__("Submit the commit using the summary and description from commit box"),
        execute: () => void 0,
        isVisible: () => false
    });

    commands.addCommand(CommandIDs.gitTerminalCommand, {
        label: trans.__("Open Git Repository in Terminal"),
        caption: trans.__("Open a New Terminal to the Git Repository"),

        execute: async args => {
            const main = (await commands.execute("terminal:create-new", args)) as MainAreaWidget<ITerminal.ITerminal>;

            try {
                if (gitModel.pathRepository !== null) {
                    const terminal = main.content;

                    terminal.session.send({
                        type: "stdin",

                        content: [
                            `cd "${gitModel.pathRepository.split("\"").join("\\\"").split("`").join("\\`")}"\n`
                        ]
                    });
                }

                return main;
            } catch (e) {
                console.error(e);
                main.dispose();
            }
        },

        isEnabled: () => gitModel.pathRepository !== null && app.serviceManager.terminals.isAvailable()
    });

    commands.addCommand(CommandIDs.gitUI, {
        label: trans.__("Git Interface"),
        caption: trans.__("Go to Git user interface"),

        execute: () => {
            try {
                shell.activateById("jp-git-sessions");
            } catch (err) {
                console.error("Fail to open Git tab.");
            }
        }
    });

    commands.addCommand(CommandIDs.gitInit, {
        label: trans.__("Initialize a Repository"),
        caption: trans.__("Create an empty Git repository or reinitialize an existing one"),

        execute: async () => {
            const currentPath = fileBrowserModel.path;

            const result = await showDialog({
                title: trans.__("Initialize a Repository"),
                body: trans.__("Do you really want to make this directory a Git Repo?"),

                buttons: [Dialog.cancelButton({
                    label: trans.__("Cancel")
                }), Dialog.warnButton({
                    label: trans.__("Yes")
                })]
            });

            if (result.button.accept) {
                logger.log({
                    message: trans.__("Initializing…"),
                    level: Level.RUNNING
                });

                try {
                    await gitModel.init(currentPath);
                    gitModel.pathRepository = currentPath;

                    logger.log({
                        message: trans.__("Git repository initialized."),
                        level: Level.SUCCESS
                    });
                } catch (error) {
                    console.error(
                        trans.__("Encountered an error when initializing the repository. Error: "),
                        error
                    );

                    logger.log({
                        message: trans.__("Failed to initialize the Git repository"),
                        level: Level.ERROR,
                        error: error as Error
                    });
                }
            }
        },

        isEnabled: () => gitModel.pathRepository === null
    });

    commands.addCommand(CommandIDs.gitOpenUrl, {
        label: args => trans.__(args["text"] as string),

        execute: args => {
            const url = args["url"] as string;
            window.open(url);
        }
    });

    commands.addCommand(CommandIDs.gitToggleSimpleStaging, {
        label: trans.__("Simple staging"),
        isToggled: () => !!settings.composite["simpleStaging"],

        execute: args => {
            settings.set("simpleStaging", !settings.composite["simpleStaging"]);
        }
    });

    commands.addCommand(CommandIDs.gitToggleDoubleClickDiff, {
        label: trans.__("Double click opens diff"),
        isToggled: () => !!settings.composite["doubleClickDiff"],

        execute: args => {
            settings.set("doubleClickDiff", !settings.composite["doubleClickDiff"]);
        }
    });

    commands.addCommand(CommandIDs.gitManageRemote, {
        label: trans.__("Manage Remote Repositories"),
        caption: trans.__("Manage Remote Repositories"),
        isEnabled: () => gitModel.pathRepository !== null,

        execute: () => {
            if (gitModel.pathRepository === null) {
                console.warn(trans.__("Not in a Git repository. Unable to add a remote."));
                return;
            }

            const widgetId = "git-dialog-ManageRemote";
            let anchor = document.querySelector<HTMLDivElement>(`#${widgetId}`);

            if (!anchor) {
                anchor = document.createElement("div");
                anchor.id = widgetId;
                document.body.appendChild(anchor);
            }

            const dialog = ReactWidget.create(
                <ManageRemoteDialogue trans={trans} model={gitModel} onClose={() => dialog.dispose()} />
            );

            Widget.attach(dialog, anchor);
        }
    });

    commands.addCommand(CommandIDs.gitOpenGitignore, {
        label: trans.__("Open .gitignore"),
        caption: trans.__("Open .gitignore"),
        isEnabled: () => gitModel.pathRepository !== null,

        execute: async () => {
            await gitModel.ensureGitignore();
        }
    });

    commands.addCommand(CommandIDs.gitPush, {
        label: args => (args["advanced"] as boolean) ? trans.__("Push to Remote (Advanced)") : trans.__("Push to Remote"),
        caption: trans.__("Push code to remote repository"),
        isEnabled: () => gitModel.pathRepository !== null,

        execute: async args => {
            try {
                let remote;
                let force;

                if (args["advanced"] as boolean) {
                    const result = await showDialog({
                        title: trans.__("Please select push options."),
                        body: new AdvancedPushForm(trans, gitModel),

                        buttons: [Dialog.cancelButton({
                            label: trans.__("Cancel")
                        }), Dialog.okButton({
                            label: trans.__("Proceed")
                        })]
                    });

                    if (result.button.accept) {
                        remote = result.value.remoteName;
                        force = result.value.force;
                    } else {
                        return;
                    }
                }

                logger.log({
                    level: Level.RUNNING,
                    message: trans.__("Pushing…")
                });

                const details = await showGitOperationDialog(gitModel, force ? Operation.ForcePush : Operation.Push, trans, (args = {
                    remote
                }));

                logger.log({
                    message: trans.__("Successfully pushed"),
                    level: Level.SUCCESS,
                    details
                });
            } catch (error: any) {
                if (error.name !== "CancelledError") {
                    console.error(trans.__("Encountered an error when pushing changes. Error: "), error);

                    logger.log({
                        message: trans.__("Failed to push"),
                        level: Level.ERROR,
                        error: error as Error
                    });
                } else {
                    return logger.log({
                        message: "",
                        level: Level.INFO
                    });
                }
            }
        }
    });

    commands.addCommand(CommandIDs.gitPull, {
        label: args => (args.force ? trans.__("Pull from Remote (Force)") : trans.__("Pull from Remote")),
        caption: args => args.force ? trans.__("Discard all current changes and pull from remote repository") : trans.__("Pull latest code from remote repository"),
        isEnabled: () => gitModel.pathRepository !== null,

        execute: async args => {
            try {
                if (args.force) {
                    await discardAllChanges(gitModel, trans, args.fallback as boolean);
                }

                logger.log({
                    level: Level.RUNNING,
                    message: trans.__("Pulling…")
                });

                const details = await showGitOperationDialog(gitModel, Operation.Pull, trans);

                logger.log({
                    message: trans.__("Successfully pulled"),
                    level: Level.SUCCESS,
                    details
                });
            } catch (error: any) {
                if (error.name !== "CancelledError") {
                    console.error("Encountered an error when pulling changes. Error: ", error);
                    const errorMsg = typeof error === "string" ? error : (error as Error).message;

                    if (errorMsg.toLowerCase().includes("your local changes to the following files would be overwritten by merge")) {
                        await commands.execute(CommandIDs.gitPull, {
                            force: true,
                            fallback: true
                        });
                    } else {
                        if ((error as any).cancelled) {
                            logger.log({
                                message: "",
                                level: Level.INFO
                            });
                        } else {
                            logger.log({
                                message: trans.__("Failed to pull"),
                                level: Level.ERROR,
                                error
                            });
                        }
                    }
                } else {
                    return logger.log({
                        message: "",
                        level: Level.INFO
                    });
                }
            }
        }
    });

    commands.addCommand(CommandIDs.gitResetToRemote, {
        label: trans.__("Reset to Remote"),
        caption: trans.__("Reset Current Branch to Remote State"),
        isEnabled: () => gitModel.pathRepository !== null,

        execute: async () => {
            const result = await showDialog({
                title: trans.__("Reset to Remote"),

                body: new CheckboxForm(trans.__(
                    "To bring the current branch to the state of its corresponding remote tracking branch,             a hard reset will be performed, which may result in some files being permanently deleted             and some changes being permanently discarded. Are you sure you want to proceed?             This action cannot be undone."
                ), trans.__("Close all opened files to avoid conflicts")),

                buttons: [Dialog.cancelButton({
                    label: trans.__("Cancel")
                }), Dialog.warnButton({
                    label: trans.__("Proceed")
                })]
            });

            if (result.button.accept) {
                try {
                    if (result.value.checked) {
                        logger.log({
                            message: trans.__("Closing all opened files..."),
                            level: Level.RUNNING
                        });

                        await fileBrowserModel.manager.closeAll();
                    }

                    logger.log({
                        message: trans.__("Resetting..."),
                        level: Level.RUNNING
                    });

                    await gitModel.resetToCommit(gitModel.status.remote);

                    logger.log({
                        message: trans.__("Successfully reset"),
                        level: Level.SUCCESS,
                        details: trans.__("Successfully reset the current branch to its remote state")
                    });
                } catch (error) {
                    console.error(
                        "Encountered an error when resetting the current branch to its remote state. Error: ",
                        error
                    );

                    logger.log({
                        message: trans.__("Reset failed"),
                        level: Level.ERROR,
                        error
                    });
                }
            }
        }
    });

    commands.addCommand(CommandIDs.gitShowDiff, {
        label: trans.__("Show Diff"),
        caption: trans.__("Display a file diff."),

        execute: async args => {
            const {
                model,
                isText
            } = args as any as {
                model: Git.Diff.IModel;
                isText?: boolean;
            };

            const fullPath = PathExt.join(model.repositoryPath ?? "/", model.filename);
            const buildDiffWidget = getDiffProvider(fullPath) ?? (isText && createPlainTextDiff);

            if (buildDiffWidget) {
                const id = `git-diff-${fullPath}-${model.reference.label}-${model.challenger.label}`;
                const mainAreaItems = shell.widgets("main");
                let mainAreaItem = mainAreaItems.next();

                while (mainAreaItem) {
                    if (mainAreaItem.id === id) {
                        shell.activateById(id);
                        break;
                    }

                    mainAreaItem = mainAreaItems.next();
                }

                if (!mainAreaItem) {
                    const content = new Panel();
                    const modelIsLoading = new PromiseDelegate<void>();

                    const diffWidget = (mainAreaItem = new MainAreaWidget<Panel>({
                        content,
                        reveal: modelIsLoading.promise
                    }));

                    diffWidget.id = id;
                    diffWidget.title.label = PathExt.basename(model.filename);
                    diffWidget.title.caption = fullPath;
                    diffWidget.title.icon = diffIcon;
                    diffWidget.title.closable = true;
                    diffWidget.title.className = "jp-git-diff-title";
                    diffWidget.addClass("jp-git-diff-parent-widget");
                    shell.add(diffWidget, "main");
                    shell.activateById(diffWidget.id);

                    try {
                        const widget = await buildDiffWidget(model, diffWidget.toolbar, translator);
                        diffWidget.toolbar.addItem("spacer", Toolbar.createSpacerItem());

                        if (model.hasConflict) {
                            const resolveButton = new ToolbarButton({
                                label: trans.__("Mark as resolved"),

                                onClick: async () => {
                                    if (!widget.isFileResolved) {
                                        const result = await showDialog({
                                            title: trans.__("Resolve with conflicts"),

                                            body: trans.__(
                                                "Are you sure you want to mark this file as resolved with merge conflicts?"
                                            )
                                        });

                                        if (!result.button.accept) {
                                            return;
                                        }
                                    }

                                    try {
                                        await serviceManager.contents.save(fullPath, await widget.getResolvedFile());
                                        await gitModel.add(model.filename);
                                        await gitModel.refresh();
                                    } catch (reason) {
                                        logger.log({
                                            message: (reason as Error).message ?? (reason as string),
                                            level: Level.ERROR
                                        });
                                    } finally {
                                        diffWidget.dispose();
                                    }
                                },

                                tooltip: trans.__("Mark file as resolved"),
                                className: "jp-git-diff-resolve"
                            });

                            diffWidget.toolbar.addItem("resolve", resolveButton);
                        } else {
                            const refreshButton = new ToolbarButton({
                                label: trans.__("Refresh"),

                                onClick: async () => {
                                    await widget.refresh();
                                    refreshButton.hide();
                                },

                                tooltip: trans.__("Refresh diff widget"),
                                className: "jp-git-diff-refresh"
                            });

                            refreshButton.hide();
                            diffWidget.toolbar.addItem("refresh", refreshButton);

                            const refresh = () => {
                                refreshButton.show();
                            };

                            model.changed.connect(refresh);
                            widget.disposed.connect(() => model.changed.disconnect(refresh));
                        }

                        modelIsLoading.resolve();
                        content.addWidget(widget);
                    } catch (reason) {
                        console.error(reason);
                        const msg = `Load Diff Model Error (${(reason as Error).message || reason})`;
                        modelIsLoading.reject(msg);
                    }

                    if (model.challenger.source === Git.Diff.SpecialRef.INDEX || model.challenger.source === Git.Diff.SpecialRef.WORKING || model.reference.source === Git.Diff.SpecialRef.INDEX || model.reference.source === Git.Diff.SpecialRef.WORKING) {
                        const maybeClose = (_: IGitExtension, status: Git.IStatus) => {
                            const targetFile = status.files.find(fileStatus => model.filename === fileStatus.from);

                            if (!targetFile || targetFile.status === "unmodified") {
                                gitModel.statusChanged.disconnect(maybeClose);
                                mainAreaItem.dispose();
                            }
                        };

                        gitModel.statusChanged.connect(maybeClose);
                    }
                }

                return mainAreaItem;
            } else {
                await showErrorMessage(trans.__("Diff Not Supported"), trans.__(
                    "Diff is not supported for %1 files.",
                    PathExt.extname(model.filename).toLocaleLowerCase()
                ));

                return null;
            }
        },

        icon: diffIcon.bindprops({
            stylesheet: "menuItem"
        })
    });

    commands.addCommand(CommandIDs.gitMerge, {
        label: trans.__("Merge Branch…"),
        caption: trans.__("Merge selected branch in the current branch"),

        execute: async args => {
            let {
                branch
            }: {
                branch?: string;
            } = args ?? {};

            if (!branch) {
                const localBranches = gitModel.branches.filter(branch => !branch.is_current_branch && !branch.is_remote_branch);
                const widgetId = "git-dialog-MergeBranch";
                let anchor = document.querySelector<HTMLDivElement>(`#${widgetId}`);

                if (!anchor) {
                    anchor = document.createElement("div");
                    anchor.id = widgetId;
                    document.body.appendChild(anchor);
                }

                const waitForDialog = new PromiseDelegate<string | null>();

                const dialog = ReactWidget.create(<MergeBranchDialog
                    currentBranch={gitModel.currentBranch.name}
                    branches={localBranches}
                    onClose={(branch?: string) => {
                        dialog.dispose();
                        waitForDialog.resolve(branch ?? null);
                    }}
                    trans={trans} />);

                Widget.attach(dialog, anchor);
                branch = await waitForDialog.promise;
            }

            if (branch) {
                logger.log({
                    level: Level.RUNNING,
                    message: trans.__("Merging branch '%1'…", branch)
                });

                try {
                    await gitModel.merge(branch);
                } catch (err) {
                    logger.log({
                        level: Level.ERROR,

                        message: trans.__(
                            "Failed to merge branch '%1' into '%2'.",
                            branch,
                            gitModel.currentBranch.name
                        ),

                        error: err as Error
                    });

                    return;
                }

                logger.log({
                    level: Level.SUCCESS,
                    message: trans.__("Branch '%1' merged into '%2'.", branch, gitModel.currentBranch.name)
                });
            }
        },

        isEnabled: () => gitModel.branches.some(branch => !branch.is_current_branch && !branch.is_remote_branch)
    });

    commands.addCommand(ContextCommandIDs.gitFileOpen, {
        label: trans.__("Open"),
        caption: pluralizedContextLabel(trans.__("Open selected file"), trans.__("Open selected files")),

        execute: async args => {
            const {
                files
            } = args as any as CommandArguments.IGitContextAction;

            for (const file of files) {
                const {
                    x,
                    y,
                    to
                } = file;

                if (x === "D" || y === "D") {
                    await showErrorMessage(trans.__("Open File Failed"), trans.__("This file has been deleted!"));
                    return;
                }

                try {
                    if (to[to.length - 1] !== "/") {
                        commands.execute("docmanager:open", {
                            path: gitModel.getRelativeFilePath(to)
                        });
                    } else {
                        console.log("Cannot open a folder here");
                    }
                } catch (err) {
                    console.error(`Fail to open ${to}.`);
                }
            }
        },

        icon: openIcon.bindprops({
            stylesheet: "menuItem"
        })
    });

    commands.addCommand(ContextCommandIDs.openFileFromDiff, {
        label: trans.__("Open File"),
        caption: trans.__("Open file from its diff view"),

        execute: async _ => {
            const domNode = app.contextMenuHitTest((node: HTMLElement) => {
                const nodeId = node.dataset.id;
                return nodeId && nodeId.substring(0, 8) === "git-diff";
            });

            if (!domNode) {
                return;
            }

            const matches = toArray(shell.widgets("main")).filter(widget => widget.id === domNode.dataset.id);

            if (matches.length === 0) {
                return;
            }

            const diffModel = (((matches[0] as MainAreaWidget).content as Panel).widgets[0] as Git.Diff.IDiffWidget).model;
            const filename = diffModel.filename;

            if (diffModel.reference.source === Git.Diff.SpecialRef.INDEX || diffModel.reference.source === Git.Diff.SpecialRef.WORKING || diffModel.challenger.source === Git.Diff.SpecialRef.INDEX || diffModel.challenger.source === Git.Diff.SpecialRef.WORKING) {
                const file = gitModel.status.files.find(fileStatus => fileStatus.from === filename);

                if (file) {
                    commands.execute(ContextCommandIDs.gitFileOpen, {
                        files: [file]
                    } as any);
                }
            } else {
                commands.execute("docmanager:open", {
                    path: gitModel.getRelativeFilePath(filename)
                });
            }
        }
    });

    commands.addCommand(ContextCommandIDs.gitFileDiff, {
        label: trans.__("Diff"),
        caption: pluralizedContextLabel(trans.__("Diff selected file"), trans.__("Diff selected files")),

        execute: async args => {
            const {
                files
            } = args as any as CommandArguments.IGitFileDiff;

            for (const file of files) {
                const {
                    context,
                    filePath,
                    previousFilePath,
                    isText,
                    status
                } = file;

                if (status === "untracked") {
                    continue;
                }

                const repositoryPath = gitModel.pathRepository;
                const filename = filePath;
                const fullPath = PathExt.join(repositoryPath, filename);
                const specialRef = status === "staged" ? Git.Diff.SpecialRef.INDEX : Git.Diff.SpecialRef.WORKING;

                const diffContext: Git.Diff.IContext = status === "unmerged" ? {
                    currentRef: "MERGE_HEAD",
                    previousRef: "HEAD",
                    baseRef: Git.Diff.SpecialRef.BASE
                } : (context ?? {
                    currentRef: specialRef,
                    previousRef: "HEAD"
                });

                const challengerRef = Git.Diff.SpecialRef[diffContext.currentRef as any] ? {
                    special: Git.Diff.SpecialRef[diffContext.currentRef as any]
                } : {
                    git: diffContext.currentRef
                };

                const props: Omit<Git.Diff.IModel, "changed" | "hasConflict"> = {
                    challenger: {
                        content: async () => {
                            return requestAPI<Git.IDiffContent>(URLExt.join(repositoryPath, "content"), "POST", {
                                filename,
                                reference: challengerRef
                            }).then(data => data.content);
                        },

                        label: (Git.Diff.SpecialRef[diffContext.currentRef as any] as any) || diffContext.currentRef,
                        source: diffContext.currentRef,
                        updateAt: Date.now()
                    },

                    filename,

                    reference: {
                        content: async () => {
                            return requestAPI<Git.IDiffContent>(URLExt.join(repositoryPath, "content"), "POST", {
                                filename: previousFilePath ?? filename,

                                reference: {
                                    git: diffContext.previousRef
                                }
                            }).then(data => data.content);
                        },

                        label: (Git.Diff.SpecialRef[diffContext.previousRef as any] as any) || diffContext.previousRef,
                        source: diffContext.previousRef,
                        updateAt: Date.now()
                    },

                    repositoryPath
                };

                if (previousFilePath) {
                    props.reference.label = `${previousFilePath} (${props.reference.label.slice(0, 7)})`;
                    props.challenger.label = `${filePath} (${props.challenger.label.slice(0, 7)})`;
                }

                if (diffContext.baseRef) {
                    props.reference.label = trans.__("Current");
                    props.challenger.label = trans.__("Incoming");

                    props.base = {
                        content: async () => {
                            return requestAPI<Git.IDiffContent>(URLExt.join(repositoryPath, "content"), "POST", {
                                filename,

                                reference: {
                                    special: Git.Diff.SpecialRef[diffContext.baseRef as any]
                                }
                            }).then(data => data.content);
                        },

                        label: trans.__("Result"),
                        source: diffContext.baseRef,
                        updateAt: Date.now()
                    };
                }

                const model = new DiffModel(props);

                const widget = await commands.execute(CommandIDs.gitShowDiff, {
                    model,
                    isText
                } as any);

                if (widget) {
                    if (diffContext.previousRef === "HEAD") {
                        const updateHead = () => {
                            model.reference = {
                                ...model.reference,
                                updateAt: Date.now()
                            };
                        };

                        gitModel.headChanged.connect(updateHead);

                        widget.disposed.connect(() => {
                            gitModel.headChanged.disconnect(updateHead);
                        });
                    }

                    if (diffContext.currentRef === Git.Diff.SpecialRef.WORKING) {
                        const updateCurrent = (m: ContentsManager, change: Contents.IChangedArgs) => {
                            const updateAt = new Date(change.newValue.last_modified).valueOf();

                            if (change.newValue.path === fullPath && model.challenger.updateAt !== updateAt) {
                                model.challenger = {
                                    ...model.challenger,
                                    updateAt
                                };
                            }
                        };

                        app.serviceManager.contents.fileChanged.connect(updateCurrent);

                        widget.disposed.connect(() => {
                            app.serviceManager.contents.fileChanged.disconnect(updateCurrent);
                        });
                    }
                }
            }
        },

        icon: diffIcon.bindprops({
            stylesheet: "menuItem"
        })
    });

    commands.addCommand(ContextCommandIDs.gitFileAdd, {
        label: trans.__("Add"),

        caption: pluralizedContextLabel(
            trans.__("Stage or track the changes to selected file"),
            trans.__("Stage or track the changes of selected files")
        ),

        execute: async args => {
            const {
                files
            } = args as any as CommandArguments.IGitContextAction;

            for (const file of files) {
                await gitModel.add(file.to);
            }
        },

        icon: addIcon.bindprops({
            stylesheet: "menuItem"
        })
    });

    commands.addCommand(ContextCommandIDs.gitFileStage, {
        label: trans.__("Stage"),

        caption: pluralizedContextLabel(
            trans.__("Stage the changes of selected file"),
            trans.__("Stage the changes of selected files")
        ),

        execute: async args => {
            const {
                files
            } = args as any as CommandArguments.IGitContextAction;

            for (const file of files) {
                await gitModel.add(file.to);
            }
        },

        icon: addIcon.bindprops({
            stylesheet: "menuItem"
        })
    });

    commands.addCommand(ContextCommandIDs.gitFileTrack, {
        label: trans.__("Track"),

        caption: pluralizedContextLabel(
            trans.__("Start tracking selected file"),
            trans.__("Start tracking selected files")
        ),

        execute: async args => {
            const {
                files
            } = args as any as CommandArguments.IGitContextAction;

            for (const file of files) {
                await gitModel.add(file.to);
            }
        },

        icon: addIcon.bindprops({
            stylesheet: "menuItem"
        })
    });

    commands.addCommand(ContextCommandIDs.gitFileUnstage, {
        label: trans.__("Unstage"),

        caption: pluralizedContextLabel(
            trans.__("Unstage the changes of selected file"),
            trans.__("Unstage the changes of selected files")
        ),

        execute: async args => {
            const {
                files
            } = args as any as CommandArguments.IGitContextAction;

            for (const file of files) {
                if (file.x !== "D") {
                    await gitModel.reset(file.to);
                }
            }
        },

        icon: removeIcon.bindprops({
            stylesheet: "menuItem"
        })
    });

    function representFiles(files: Git.IStatusFile[]): JSX.Element {
        const elements = files.map(file => (<li key={file.to}>
            <b>{file.to}</b>
        </li>));

        return <ul>{elements}</ul>;
    }

    commands.addCommand(ContextCommandIDs.gitFileDelete, {
        label: trans.__("Delete"),
        caption: pluralizedContextLabel(trans.__("Delete this file"), trans.__("Delete these files")),

        execute: async args => {
            const {
                files
            } = args as any as CommandArguments.IGitContextAction;

            const fileList = representFiles(files);

            const result = await showDialog({
                title: trans.__("Delete Files"),

                body: (<span>
                    {trans.__(
                        "Are you sure you want to permanently delete the following files?               This action cannot be undone."
                    )}
                    {fileList}
                </span>),

                buttons: [Dialog.cancelButton({
                    label: trans.__("Cancel")
                }), Dialog.warnButton({
                    label: trans.__("Delete")
                })]
            });

            if (result.button.accept) {
                for (const file of files) {
                    try {
                        await app.commands.execute("docmanager:delete-file", {
                            path: gitModel.getRelativeFilePath(file.to)
                        });
                    } catch (reason) {
                        showErrorMessage(trans.__("Deleting %1 failed.", file.to), reason, [Dialog.warnButton({
                            label: trans.__("Dismiss")
                        })]);
                    }
                }
            }
        },

        icon: closeIcon.bindprops({
            stylesheet: "menuItem"
        })
    });

    commands.addCommand(ContextCommandIDs.gitFileDiscard, {
        label: trans.__("Discard"),

        caption: pluralizedContextLabel(
            trans.__("Discard recent changes of selected file"),
            trans.__("Discard recent changes of selected files")
        ),

        execute: async args => {
            const {
                files
            } = args as any as CommandArguments.IGitContextAction;

            const fileList = representFiles(files);

            const result = await showDialog({
                title: trans.__("Discard changes"),

                body: (<span>
                    {trans.__(
                        "Are you sure you want to permanently discard changes to the following files?               This action cannot be undone."
                    )}
                    {fileList}
                </span>),

                buttons: [Dialog.cancelButton({
                    label: trans.__("Cancel")
                }), Dialog.warnButton({
                    label: trans.__("Discard")
                })]
            });

            if (result.button.accept) {
                for (const file of files) {
                    try {
                        if (file.status === "staged" || file.status === "partially-staged") {
                            await gitModel.reset(file.to);
                        }

                        if (file.status === "unstaged" || (file.status === "partially-staged" && file.x !== "A")) {
                            await gitModel.checkout({
                                filename: file.to
                            });
                        }
                    } catch (reason) {
                        showErrorMessage(
                            trans.__("Discard changes for %1 failed.", file.to),
                            reason,
                            [Dialog.warnButton({
                                label: trans.__("Dismiss")
                            })]
                        );
                    }
                }
            }
        },

        icon: discardIcon.bindprops({
            stylesheet: "menuItem"
        })
    });

    commands.addCommand(ContextCommandIDs.gitIgnore, {
        label: pluralizedContextLabel(
            trans.__("Ignore this file (add to .gitignore)"),
            trans.__("Ignore these files (add to .gitignore)")
        ),

        caption: pluralizedContextLabel(
            trans.__("Ignore this file (add to .gitignore)"),
            trans.__("Ignore these files (add to .gitignore)")
        ),

        execute: async args => {
            const {
                files
            } = args as any as CommandArguments.IGitContextAction;

            for (const file of files) {
                if (file) {
                    await gitModel.ignore(file.to, false);
                }
            }
        }
    });

    commands.addCommand(ContextCommandIDs.gitIgnoreExtension, {
        label: args => {
            const {
                files
            } = args as any as CommandArguments.IGitContextAction;

            const extensions = files.map(file => PathExt.extname(file.to)).filter(extension => extension.length > 0).filter((item, index, arr) => arr.indexOf(item) === index);

            return trans._n(
                "Ignore %2 extension (add to .gitignore)",
                "Ignore %2 extensions (add to .gitignore)",
                extensions.length,
                extensions.join(", ")
            );
        },

        caption: pluralizedContextLabel(
            trans.__("Ignore this file extension (add to .gitignore)"),
            trans.__("Ignore these files extension (add to .gitignore)")
        ),

        execute: async args => {
            const {
                files
            } = args as any as CommandArguments.IGitContextAction;

            for (const selectedFile of files) {
                if (selectedFile) {
                    const extension = PathExt.extname(selectedFile.to);

                    if (extension.length > 0) {
                        const result = await showDialog({
                            title: trans.__("Ignore file extension"),

                            body: trans.__(
                                "Are you sure you want to ignore all %1 files within this git repository?",
                                extension
                            ),

                            buttons: [Dialog.cancelButton(), Dialog.okButton({
                                label: trans.__("Ignore")
                            })]
                        });

                        if (result.button.label === trans.__("Ignore")) {
                            await gitModel.ignore(selectedFile.to, true);
                        }
                    }
                }
            }
        },

        isVisible: args => {
            const {
                files
            } = args as any as CommandArguments.IGitContextAction;

            return files.some(selectedFile => {
                const extension = PathExt.extname(selectedFile.to);
                return extension.length > 0;
            });
        }
    });

    commands.addCommand(ContextCommandIDs.gitFileHistory, {
        label: trans.__("History"),
        caption: trans.__("View the history of this file"),

        execute: args => {
            const {
                files
            } = args as any as CommandArguments.IGitContextAction;

            const file = files[0];

            if (!file) {
                return;
            }

            gitModel.selectedHistoryFile = file;
            shell.activateById("jp-git-sessions");
        },

        isEnabled: args => {
            const {
                files
            } = args as any as CommandArguments.IGitContextAction;

            return files.length === 1;
        },

        icon: historyIcon.bindprops({
            stylesheet: "menuItem"
        })
    });

    commands.addCommand(ContextCommandIDs.gitNoAction, {
        label: trans.__("No actions available"),
        isEnabled: () => false,
        execute: () => void 0
    });
}

function addCommands(
    app: JupyterFrontEnd,
    gitModel: GitExtension,
    editorFactory: IEditorFactoryService,
    languageRegistry: IEditorLanguageRegistry,
    fileBrowserModel: FileBrowserModel,
    settings: ISettingRegistry.ISettings,
    translator: ITranslator
): void {
    const {
        commands,
        shell,
        serviceManager
    } = app;

    const trans = translator.load("jupyterlab_git");

    commands.addCommand(CommandIDs.gitSubmitCommand, {
        label: trans.__("Commit from the Commit Box"),
        caption: trans.__("Submit the commit using the summary and description from commit box"),
        execute: () => void 0,
        isVisible: () => false
    });

    commands.addCommand(CommandIDs.gitTerminalCommand, {
        label: trans.__("Open Git Repository in Terminal"),
        caption: trans.__("Open a New Terminal to the Git Repository"),

        execute: async args => {
            const main = (await commands.execute("terminal:create-new", args)) as MainAreaWidget<ITerminal.ITerminal>;

            try {
                if (gitModel.pathRepository !== null) {
                    const terminal = main.content;

                    terminal.session.send({
                        type: "stdin",

                        content: [
                            `cd "${gitModel.pathRepository.split("\"").join("\\\"").split("`").join("\\`")}"\n`
                        ]
                    });
                }

                return main;
            } catch (e) {
                console.error(e);
                main.dispose();
            }
        },

        isEnabled: () => gitModel.pathRepository !== null && app.serviceManager.terminals.isAvailable()
    });

    commands.addCommand(CommandIDs.gitUI, {
        label: trans.__("Git Interface"),
        caption: trans.__("Go to Git user interface"),

        execute: () => {
            try {
                shell.activateById("jp-git-sessions");
            } catch (err) {
                console.error("Fail to open Git tab.");
            }
        }
    });

    commands.addCommand(CommandIDs.gitInit, {
        label: trans.__("Initialize a Repository"),
        caption: trans.__("Create an empty Git repository or reinitialize an existing one"),

        execute: async () => {
            const currentPath = app.serviceManager.contents.localPath(fileBrowserModel.path);

            const result = await showDialog({
                title: trans.__("Initialize a Repository"),
                body: trans.__("Do you really want to make this directory a Git Repo?"),

                buttons: [Dialog.cancelButton({
                    label: trans.__("Cancel")
                }), Dialog.warnButton({
                    label: trans.__("Yes")
                })]
            });

            if (result.button.accept) {
                const id = Notification.emit(trans.__("Initializing…"), "in-progress", {
                    autoClose: false
                });

                try {
                    await gitModel.init(currentPath);
                    gitModel.pathRepository = currentPath;

                    Notification.update({
                        id,
                        message: trans.__("Git repository initialized."),
                        type: "success",
                        autoClose: 5000
                    });
                } catch (error) {
                    console.error(
                        trans.__("Encountered an error when initializing the repository. Error: "),
                        error
                    );

                    Notification.update({
                        id,
                        message: trans.__("Failed to initialize the Git repository"),
                        type: "error",
                        ...showError(error as Error, trans)
                    });
                }
            }
        },

        isEnabled: () => gitModel.pathRepository === null
    });

    commands.addCommand(CommandIDs.gitOpenUrl, {
        label: args => trans.__(args["text"] as string),

        execute: args => {
            const url = args["url"] as string;
            window.open(url);
        }
    });

    commands.addCommand(CommandIDs.gitToggleSimpleStaging, {
        label: trans.__("Simple staging"),
        isToggled: () => !!settings.composite["simpleStaging"],

        execute: args => {
            settings.set("simpleStaging", !settings.composite["simpleStaging"]);
        }
    });

    commands.addCommand(CommandIDs.gitToggleDoubleClickDiff, {
        label: trans.__("Double click opens diff"),
        isToggled: () => !!settings.composite["doubleClickDiff"],

        execute: args => {
            settings.set("doubleClickDiff", !settings.composite["doubleClickDiff"]);
        }
    });

    commands.addCommand(CommandIDs.gitManageRemote, {
        label: trans.__("Manage Remote Repositories"),
        caption: trans.__("Manage Remote Repositories"),
        isEnabled: () => gitModel.pathRepository !== null,

        execute: () => {
            if (gitModel.pathRepository === null) {
                console.warn(trans.__("Not in a Git repository. Unable to add a remote."));
                return;
            }

            const widgetId = "git-dialog-ManageRemote";
            let anchor = document.querySelector<HTMLDivElement>(`#${widgetId}`);

            if (!anchor) {
                anchor = document.createElement("div");
                anchor.id = widgetId;
                document.body.appendChild(anchor);
            }

            const dialog = ReactWidget.create(
                <ManageRemoteDialogue trans={trans} model={gitModel} onClose={() => dialog.dispose()} />
            );

            Widget.attach(dialog, anchor);
        }
    });

    async function showGitignore(error: any) {
        const model = new CodeEditor.Model({});
        const repoPath = gitModel.getRelativeFilePath();
        const id = repoPath + "/.git-ignore";
        const contentData = await gitModel.readGitIgnore();
        const gitIgnoreWidget = find(shell.widgets(), shellWidget => shellWidget.id === id);

        if (gitIgnoreWidget) {
            shell.activateById(id);
            return;
        }

        model.sharedModel.setSource(contentData ? contentData : "");

        const editor = new CodeEditorWrapper({
            factory: editorFactory.newDocumentEditor.bind(editorFactory),
            model: model
        });

        const modelChangedSignal = model.sharedModel.changed;

        editor.disposed.connect(() => {
            model.dispose();
        });

        const preview = new MainAreaWidget({
            content: editor
        });

        preview.title.label = ".gitignore";
        preview.id = id;
        preview.title.icon = gitIcon;
        preview.title.closable = true;
        preview.title.caption = repoPath + "/.gitignore";

        const saveButton = new ToolbarButton({
            icon: saveIcon,

            onClick: async () => {
                if (saved) {
                    return;
                }

                const newContent = model.sharedModel.getSource();

                try {
                    await gitModel.writeGitIgnore(newContent);
                    preview.title.className = "";
                    saved = true;
                } catch (error) {
                    console.log("Could not save .gitignore");
                }
            },

            tooltip: trans.__("Saves .gitignore")
        });

        let saved = true;
        preview.toolbar.addItem("save", saveButton);
        shell.add(preview);

        modelChangedSignal.connect(() => {
            if (saved) {
                saved = false;
                preview.title.className = "not-saved";
            }
        });
    }

    async function showGitignoreHiddenFile(error: any, hidePrompt: boolean) {
        if (hidePrompt) {
            return showGitignore(error);
        }

        const result = await showDialog({
            title: trans.__("Warning: The .gitignore file is a hidden file."),

            body: (<div>
                {trans.__(
                    "Hidden files by default cannot be accessed with the regular code editor. In order to open the .gitignore file you must:"
                )}
                <ol>
                    <li>
                        {trans.__(
                            "Print the command below to create a jupyter_server_config.py file with defaults commented out. If you already have the file located in .jupyter, skip this step."
                        )}
                        <div
                            style={{
                                padding: "0.5rem"
                            }}>{"jupyter server --generate-config"}</div>
                    </li>
                    <li>
                        {trans.__(
                            "Open jupyter_server_config.py, uncomment out the following line and set it to True:"
                        )}
                        <div
                            style={{
                                padding: "0.5rem"
                            }}>{"c.ContentsManager.allow_hidden = False"}</div>
                    </li>
                </ol>
            </div>),

            buttons: [Dialog.cancelButton({
                label: trans.__("Cancel")
            }), Dialog.okButton({
                label: trans.__("Show .gitignore file anyways")
            })],

            checkbox: {
                label: trans.__("Do not show this warning again"),
                checked: false
            }
        });

        if (result.button.accept) {
            settings.set("hideHiddenFileWarning", result.isChecked);
            showGitignore(error);
        }
    }

    commands.addCommand(CommandIDs.gitOpenGitignore, {
        label: trans.__("Open .gitignore"),
        caption: trans.__("Open .gitignore"),
        isEnabled: () => gitModel.pathRepository !== null,

        execute: async () => {
            try {
                await gitModel.ensureGitignore();
            } catch (error: any) {
                if (error?.name === "hiddenFile") {
                    await showGitignoreHiddenFile(error, settings.composite["hideHiddenFileWarning"] as boolean);
                }
            }
        }
    });

    commands.addCommand(CommandIDs.gitPush, {
        label: args => (args["advanced"] as boolean) ? trans.__("Push to Remote (Advanced)") : trans.__("Push to Remote"),
        caption: trans.__("Push code to remote repository"),
        isEnabled: () => gitModel.pathRepository !== null,

        execute: async args => {
            let id: string | null = null;

            try {
                let remote;
                let force;

                if (args["advanced"] as boolean) {
                    const result = await showDialog({
                        title: trans.__("Please select push options."),
                        body: new AdvancedPushForm(trans, gitModel),

                        buttons: [Dialog.cancelButton({
                            label: trans.__("Cancel")
                        }), Dialog.okButton({
                            label: trans.__("Proceed")
                        })]
                    });

                    if (result.button.accept && result.value) {
                        remote = result.value.remoteName;
                        force = result.value.force;
                    } else {
                        return;
                    }
                }

                id = Notification.emit(trans.__("Pushing…"), "in-progress", {
                    autoClose: false
                });

                const details = await showGitOperationDialog(gitModel, force ? Operation.ForcePush : Operation.Push, trans, (args = {
                    remote
                }));

                Notification.update({
                    id,
                    message: trans.__("Successfully pushed"),
                    type: "success",
                    ...showDetails(details, trans)
                });
            } catch (error: any) {
                if (error.name !== "CancelledError") {
                    console.error(trans.__("Encountered an error when pushing changes. Error: "), error);
                    const message = trans.__("Failed to push");
                    const options = showError(error as Error, trans);

                    if (id) {
                        Notification.update({
                            id,
                            message,
                            type: "error",
                            ...options
                        });
                    } else {
                        Notification.error(message, options);
                    }
                } else {
                    if (id) {
                        Notification.dismiss(id);
                    }
                }
            }
        }
    });

    commands.addCommand(CommandIDs.gitPull, {
        label: args => (args.force ? trans.__("Pull from Remote (Force)") : trans.__("Pull from Remote")),
        caption: args => args.force ? trans.__("Discard all current changes and pull from remote repository") : trans.__("Pull latest code from remote repository"),
        isEnabled: () => gitModel.pathRepository !== null,

        execute: async args => {
            let id: string | null = null;

            try {
                if (args.force) {
                    await discardAllChanges(gitModel, trans, args.fallback as boolean);
                }

                id = Notification.emit(trans.__("Pulling…"), "in-progress", {
                    autoClose: false
                });

                const details = await showGitOperationDialog(gitModel, Operation.Pull, trans);

                Notification.update({
                    id,
                    message: trans.__("Successfully pulled"),
                    type: "success",
                    ...showDetails(details, trans)
                });
            } catch (error: any) {
                if (error.name !== "CancelledError") {
                    console.error("Encountered an error when pulling changes. Error: ", error);
                    const errorMsg = typeof error === "string" ? error : (error as Error).message;

                    if (errorMsg.toLowerCase().includes("your local changes to the following files would be overwritten by merge")) {
                        await commands.execute(CommandIDs.gitPull, {
                            force: true,
                            fallback: true
                        });
                    } else {
                        if ((error as any).cancelled) {
                            if (id) {
                                Notification.dismiss(id);
                            }
                        } else {
                            const message = trans.__("Failed to pull");
                            const options = showError(error, trans);

                            if (id) {
                                Notification.update({
                                    id,
                                    message,
                                    ...options
                                });
                            } else {
                                Notification.error(message, options);
                            }
                        }
                    }
                } else {
                    if (id) {
                        Notification.dismiss(id);
                    }
                }
            }
        }
    });

    commands.addCommand(CommandIDs.gitResetToRemote, {
        label: trans.__("Reset to Remote"),
        caption: trans.__("Reset Current Branch to Remote State"),
        isEnabled: () => gitModel.pathRepository !== null,

        execute: async () => {
            const result = await showDialog({
                title: trans.__("Reset to Remote"),

                body: new CheckboxForm(trans.__(
                    "To bring the current branch to the state of its corresponding remote tracking branch,             a hard reset will be performed, which may result in some files being permanently deleted             and some changes being permanently discarded. Are you sure you want to proceed?             This action cannot be undone."
                ), trans.__("Close all opened files to avoid conflicts")),

                buttons: [Dialog.cancelButton({
                    label: trans.__("Cancel")
                }), Dialog.warnButton({
                    label: trans.__("Proceed")
                })]
            });

            if (result.button.accept) {
                let id: string | null = null;

                try {
                    if (result.value?.checked) {
                        id = Notification.emit(trans.__("Closing all opened files..."), "in-progress");
                        await fileBrowserModel.manager.closeAll();
                    }

                    const message = trans.__("Resetting...");

                    if (id) {
                        Notification.update({
                            id,
                            message
                        });
                    } else {
                        id = Notification.emit(message, "in-progress", {
                            autoClose: false
                        });
                    }

                    await gitModel.resetToCommit(gitModel.status.remote ?? undefined);

                    Notification.update({
                        id,
                        message: trans.__("Successfully reset"),
                        type: "success",

                        ...showDetails(
                            trans.__("Successfully reset the current branch to its remote state"),
                            trans
                        )
                    });
                } catch (error) {
                    console.error(
                        "Encountered an error when resetting the current branch to its remote state. Error: ",
                        error
                    );

                    const message = trans.__("Reset failed");
                    const options = showError(error as Error, trans);

                    if (id) {
                        Notification.update({
                            id,
                            type: "error",
                            message,
                            ...options
                        });
                    } else {
                        Notification.error(message, options);
                    }
                }
            }
        }
    });

    commands.addCommand(CommandIDs.gitShowDiff, {
        label: trans.__("Show Diff"),
        caption: trans.__("Display a file diff."),

        execute: async args => {
            const {
                model,
                isText,
                isPreview
            } = args as any as {
                model: Git.Diff.IModel;
                isText?: boolean;
                isPreview?: boolean;
            };

            const fullPath = PathExt.join(model.repositoryPath ?? "/", model.filename);

            const buildDiffWidget = getDiffProvider(fullPath) ?? (isText && (options => createPlainTextDiff({
                ...options,
                editorFactory: editorFactory.newInlineEditor.bind(editorFactory),
                languageRegistry
            })));

            if (buildDiffWidget) {
                const id = `git-diff-${fullPath}-${model.reference.label}-${model.challenger.label}`;
                const mainAreaItems = shell.widgets("main");
                let mainAreaItem: Widget | null = null;

                for (const item of mainAreaItems) {
                    if (item.id === id) {
                        shell.activateById(id);
                        mainAreaItem = item;
                        break;
                    }
                }

                if (!mainAreaItem) {
                    const content = new Panel();
                    const modelIsLoading = new PromiseDelegate<void>();

                    const diffWidget = (mainAreaItem = new PreviewMainAreaWidget<Panel>({
                        content,
                        reveal: modelIsLoading.promise,
                        isPreview
                    }));

                    diffWidget.id = id;
                    diffWidget.title.label = PathExt.basename(model.filename);
                    diffWidget.title.caption = fullPath;
                    diffWidget.title.icon = diffIcon;
                    diffWidget.title.closable = true;
                    diffWidget.title.className = "jp-git-diff-title";
                    diffWidget.addClass("jp-git-diff-parent-widget");
                    shell.add(diffWidget, "main");
                    shell.activateById(diffWidget.id);
                    const dockPanel = (app.shell as any)._dockPanel as DockPanel;
                    let tabPosition = -1;

                    const tabBar = Array.from(dockPanel.tabBars()).find(bar => {
                        tabPosition = bar.titles.indexOf(diffWidget.title);
                        return tabPosition !== -1;
                    });

                    if (tabBar) {
                        PreviewMainAreaWidget.pinWidget(tabPosition, tabBar, diffWidget);
                    }

                    try {
                        const widget = await buildDiffWidget({
                            model,
                            toolbar: diffWidget.toolbar,
                            translator
                        });

                        diffWidget.toolbar.addItem("spacer", Toolbar.createSpacerItem());

                        if (model.hasConflict) {
                            const resolveButton = new ToolbarButton({
                                label: trans.__("Mark as resolved"),

                                onClick: async () => {
                                    if (!widget.isFileResolved) {
                                        const result = await showDialog({
                                            title: trans.__("Resolve with conflicts"),

                                            body: trans.__(
                                                "Are you sure you want to mark this file as resolved with merge conflicts?"
                                            )
                                        });

                                        if (!result.button.accept) {
                                            return;
                                        }
                                    }

                                    try {
                                        await serviceManager.contents.save(fullPath, await widget.getResolvedFile());
                                        await gitModel.add(model.filename);
                                        await gitModel.refresh();
                                    } catch (reason) {
                                        Notification.error((reason as Error).message ?? (reason as string));
                                    } finally {
                                        diffWidget.dispose();
                                    }
                                },

                                tooltip: trans.__("Mark file as resolved"),
                                className: "jp-git-diff-resolve"
                            });

                            diffWidget.toolbar.addItem("resolve", resolveButton);
                        } else {
                            const refreshButton = new ToolbarButton({
                                label: trans.__("Refresh"),

                                onClick: async () => {
                                    await widget.refresh();
                                    refreshButton.hide();
                                },

                                tooltip: trans.__("Refresh diff widget"),
                                className: "jp-git-diff-refresh"
                            });

                            refreshButton.hide();
                            diffWidget.toolbar.addItem("refresh", refreshButton);

                            const refresh = () => {
                                refreshButton.show();
                            };

                            model.changed.connect(refresh);
                            widget.disposed.connect(() => model.changed.disconnect(refresh));
                        }

                        modelIsLoading.resolve();
                        content.addWidget(widget);
                    } catch (reason) {
                        console.error(reason);
                        const msg = `Load Diff Model Error (${(reason as Error).message || reason})`;
                        modelIsLoading.reject(msg);
                    }

                    if (model.challenger.source === Git.Diff.SpecialRef.INDEX || model.challenger.source === Git.Diff.SpecialRef.WORKING || model.reference.source === Git.Diff.SpecialRef.INDEX || model.reference.source === Git.Diff.SpecialRef.WORKING) {
                        const maybeClose = (_: IGitExtension, status: Git.IStatus) => {
                            const targetFile = status.files.find(fileStatus => model.filename === fileStatus.from);

                            if (!targetFile || targetFile.status === "unmodified") {
                                gitModel.statusChanged.disconnect(maybeClose);
                                mainAreaItem!.dispose();
                            }
                        };

                        gitModel.statusChanged.connect(maybeClose);
                    }
                }

                return mainAreaItem;
            } else {
                await showErrorMessage(trans.__("Diff Not Supported"), trans.__(
                    "Diff is not supported for %1 files.",
                    PathExt.extname(model.filename).toLocaleLowerCase()
                ));

                return null;
