            const filename = diffModel.filename;

            if (diffModel.reference.source === Git.Diff.SpecialRef.INDEX || diffModel.reference.source === Git.Diff.SpecialRef.WORKING || diffModel.challenger.source === Git.Diff.SpecialRef.INDEX || diffModel.challenger.source === Git.Diff.SpecialRef.WORKING) {
