        },

        isEnabled: args => {
            const {
                files
            } = args as any as CommandArguments.IGitContextAction;

            return files.length === 1;
        },

        icon: historyIcon.bindprops({
            stylesheet: "menuItem"
        })
    });

    commands.addCommand(ContextCommandIDs.gitNoAction, {
        label: trans.__("No actions available"),
        isEnabled: () => false,
        execute: () => void 0
    });

    commands.addCommand(ContextCommandIDs.gitTagAdd, {
        label: trans.__("Add Tag"),
        caption: trans.__("Add tag pointing to selected commit"),

        execute: async args => {
            const commit = args as any as CommandArguments.IGitCommitInfo;
            const widgetId = "git-dialog-AddTag";
            let anchor = document.querySelector<HTMLDivElement>(`#${widgetId}`);

            if (!anchor) {
                anchor = document.createElement("div");
                anchor.id = widgetId;
                document.body.appendChild(anchor);
            }

            const tagDialog = true;
            const isSingleCommit = true;
            const waitForDialog = new PromiseDelegate<string | null>();

            const dialog = ReactWidget.create(<NewTagDialogBox
                pastCommits={[commit.commit]}
                model={gitModel}
                trans={trans}
                open={tagDialog}
                onClose={(tagName?: string) => {
                    dialog.dispose();
                    waitForDialog.resolve(tagName ?? null);
                }}
                isSingleCommit={isSingleCommit} />);

            Widget.attach(dialog, anchor);
            const tagName = await waitForDialog.promise;

            if (tagName) {
                const id = Notification.emit(
                    trans.__("Create tag pointing to '%1'...", commit.commit.commit_msg),
                    "in-progress"
                );

                try {
                    await gitModel.setTag(tagName, commit.commit.commit);
                } catch (err) {
                    Notification.update({
                        id,
                        message: trans.__("Failed to create tag '%1' poining to '%2'.", tagName, commit),
                        type: "error",
                        ...showError(err as any, trans)
                    });

                    return;
                }

                Notification.update({
                    id,
                    message: trans.__("Created tag '%1' pointing to '%2'.", tagName, commit),
                    type: "success"
                });
            }
        },

        icon: tagIcon.bindprops({
            stylesheet: "menuItem"
        })
    });
}

function addCommands(
    app: JupyterFrontEnd,
    gitModel: GitExtension,
    editorFactory: IEditorFactoryService,
    languageRegistry: IEditorLanguageRegistry,
    fileBrowserModel: FileBrowserModel,
    settings: ISettingRegistry.ISettings,
    translator: ITranslator
): void {
    const {
        commands,
        shell,
        serviceManager
    } = app;

    const trans = translator.load("jupyterlab_git");

    commands.addCommand(CommandIDs.gitSubmitCommand, {
        label: trans.__("Commit from the Commit Box"),
        caption: trans.__("Submit the commit using the summary and description from commit box"),
        execute: () => void 0,
        isVisible: () => false
    });

    commands.addCommand(CommandIDs.gitTerminalCommand, {
        label: trans.__("Open Git Repository in Terminal"),
        caption: trans.__("Open a New Terminal to the Git Repository"),

        execute: async args => {
            const cwd = gitModel.pathRepository;

            const main = (await commands.execute("terminal:create-new", {
                ...args,
                cwd
            })) as MainAreaWidget<ITerminal.ITerminal>;

            return main;
        },

        isEnabled: () => gitModel.pathRepository !== null && app.serviceManager.terminals.isAvailable()
    });

    commands.addCommand(CommandIDs.gitUI, {
        label: trans.__("Git Interface"),
        caption: trans.__("Go to Git user interface"),

        execute: () => {
            try {
                shell.activateById("jp-git-sessions");
            } catch (err) {
                console.error("Fail to open Git tab.");
            }
        }
    });

    commands.addCommand(CommandIDs.gitInit, {
        label: trans.__("Initialize a Repository"),
        caption: trans.__("Create an empty Git repository or reinitialize an existing one"),

        execute: async () => {
            const currentPath = app.serviceManager.contents.localPath(fileBrowserModel.path);

            const result = await showDialog({
                title: trans.__("Initialize a Repository"),
                body: trans.__("Do you really want to make this directory a Git Repo?"),

                buttons: [Dialog.cancelButton({
                    label: trans.__("Cancel")
                }), Dialog.warnButton({
                    label: trans.__("Yes")
                })]
            });

            if (result.button.accept) {
                const id = Notification.emit(trans.__("Initializing…"), "in-progress", {
                    autoClose: false
                });

                try {
                    await gitModel.init(currentPath);
                    gitModel.pathRepository = currentPath;

                    Notification.update({
                        id,
                        message: trans.__("Git repository initialized."),
                        type: "success",
                        autoClose: 5000
                    });
                } catch (error) {
                    console.error(
                        trans.__("Encountered an error when initializing the repository. Error: "),
                        error
                    );

                    Notification.update({
                        id,
                        message: trans.__("Failed to initialize the Git repository"),
                        type: "error",
                        ...showError(error as Error, trans)
                    });
                }
            }
        },

        isEnabled: () => gitModel.pathRepository === null
    });

    commands.addCommand(CommandIDs.gitOpenUrl, {
        label: args => trans.__(args["text"] as string),

        execute: args => {
            const url = args["url"] as string;
            window.open(url);
        }
    });

    commands.addCommand(CommandIDs.gitToggleSimpleStaging, {
        label: trans.__("Simple staging"),
        isToggled: () => !!settings.composite["simpleStaging"],

        execute: args => {
            settings.set("simpleStaging", !settings.composite["simpleStaging"]);
        }
    });

    commands.addCommand(CommandIDs.gitToggleDoubleClickDiff, {
        label: trans.__("Double click opens diff"),
        isToggled: () => !!settings.composite["doubleClickDiff"],

        execute: args => {
            settings.set("doubleClickDiff", !settings.composite["doubleClickDiff"]);
        }
    });

    commands.addCommand(CommandIDs.gitManageRemote, {
        label: trans.__("Manage Remote Repositories"),
        caption: trans.__("Manage Remote Repositories"),
        isEnabled: () => gitModel.pathRepository !== null,

        execute: () => {
            if (gitModel.pathRepository === null) {
                console.warn(trans.__("Not in a Git repository. Unable to add a remote."));
                return;
            }

            const widgetId = "git-dialog-ManageRemote";
            let anchor = document.querySelector<HTMLDivElement>(`#${widgetId}`);

            if (!anchor) {
                anchor = document.createElement("div");
                anchor.id = widgetId;
                document.body.appendChild(anchor);
            }

            const dialog = ReactWidget.create(
                <ManageRemoteDialogue trans={trans} model={gitModel} onClose={() => dialog.dispose()} />
            );

            Widget.attach(dialog, anchor);
        }
    });

    async function showGitignore(error: any) {
        const model = new CodeEditor.Model({});
        const repoPath = gitModel.getRelativeFilePath();
        const id = repoPath + "/.git-ignore";
        const contentData = await gitModel.readGitIgnore();
        const gitIgnoreWidget = find(shell.widgets(), shellWidget => shellWidget.id === id);

        if (gitIgnoreWidget) {
            shell.activateById(id);
            return;
        }

        model.sharedModel.setSource(contentData ? contentData : "");

        const editor = new CodeEditorWrapper({
            factory: editorFactory.newDocumentEditor.bind(editorFactory),
            model: model
        });

        const modelChangedSignal = model.sharedModel.changed;

        editor.disposed.connect(() => {
            model.dispose();
        });

        const preview = new MainAreaWidget({
            content: editor
        });

        preview.title.label = ".gitignore";
        preview.id = id;
        preview.title.icon = gitIcon;
        preview.title.closable = true;
        preview.title.caption = repoPath + "/.gitignore";

        const saveButton = new ToolbarButton({
            icon: saveIcon,

            onClick: async () => {
                if (saved) {
                    return;
                }

                const newContent = model.sharedModel.getSource();

                try {
                    await gitModel.writeGitIgnore(newContent);
                    preview.title.className = "";
                    saved = true;
                } catch (error) {
                    console.log("Could not save .gitignore");
                }
            },

            tooltip: trans.__("Saves .gitignore")
        });

        let saved = true;
        preview.toolbar.addItem("save", saveButton);
        shell.add(preview);

        modelChangedSignal.connect(() => {
            if (saved) {
                saved = false;
                preview.title.className = "not-saved";
            }
        });
    }

    async function showGitignoreHiddenFile(error: any, hidePrompt: boolean) {
        if (hidePrompt) {
            return showGitignore(error);
        }

        const result = await showDialog({
            title: trans.__("Warning: The .gitignore file is a hidden file."),

            body: (<div>
                {trans.__(
                    "Hidden files by default cannot be accessed with the regular code editor. In order to open the .gitignore file you must:"
                )}
                <ol>
                    <li>
                        {trans.__(
                            "Print the command below to create a jupyter_server_config.py file with defaults commented out. If you already have the file located in .jupyter, skip this step."
                        )}
                        <div
                            style={{
                                padding: "0.5rem"
                            }}>{"jupyter server --generate-config"}</div>
                    </li>
                    <li>
                        {trans.__(
                            "Open jupyter_server_config.py, uncomment out the following line and set it to True:"
                        )}
                        <div
                            style={{
                                padding: "0.5rem"
                            }}>{"c.ContentsManager.allow_hidden = False"}</div>
                    </li>
                </ol>
            </div>),

            buttons: [Dialog.cancelButton({
                label: trans.__("Cancel")
            }), Dialog.okButton({
                label: trans.__("Show .gitignore file anyways")
            })],

            checkbox: {
                label: trans.__("Do not show this warning again"),
                checked: false
            }
        });

        if (result.button.accept) {
            settings.set("hideHiddenFileWarning", result.isChecked);
            showGitignore(error);
        }
    }

    commands.addCommand(CommandIDs.gitOpenGitignore, {
        label: trans.__("Open .gitignore"),
        caption: trans.__("Open .gitignore"),
        isEnabled: () => gitModel.pathRepository !== null,

        execute: async () => {
            try {
                await gitModel.ensureGitignore();
            } catch (error: any) {
                if (error?.name === "hiddenFile") {
                    await showGitignoreHiddenFile(error, settings.composite["hideHiddenFileWarning"] as boolean);
                }
            }
        }
    });

    commands.addCommand(CommandIDs.gitPush, {
        label: args => (args["advanced"] as boolean) ? trans.__("Push to Remote (Advanced)") : trans.__("Push to Remote"),
        caption: trans.__("Push code to remote repository"),
        isEnabled: () => gitModel.pathRepository !== null,

        execute: async args => {
            let id: string | null = null;

            try {
                let remote;
                let force;

                if (args["advanced"] as boolean) {
                    const result = await showDialog({
                        title: trans.__("Please select push options."),
                        body: new AdvancedPushForm(trans, gitModel),

                        buttons: [Dialog.cancelButton({
                            label: trans.__("Cancel")
                        }), Dialog.okButton({
                            label: trans.__("Proceed")
                        })]
                    });

                    if (result.button.accept && result.value) {
                        remote = result.value.remoteName;
                        force = result.value.force;
                    } else {
                        return;
                    }
                }

                id = Notification.emit(trans.__("Pushing…"), "in-progress", {
                    autoClose: false
                });

                const details = await showGitOperationDialog(gitModel, force ? Operation.ForcePush : Operation.Push, trans, (args = {
                    remote
                }));

                Notification.update({
                    id,
                    message: trans.__("Successfully pushed"),
                    type: "success",
                    ...showDetails(details, trans)
                });
            } catch (error: any) {
                if (error.name !== "CancelledError") {
                    console.error(trans.__("Encountered an error when pushing changes. Error: "), error);
                    const message = trans.__("Failed to push");
                    const options = showError(error as Error, trans);

                    if (id) {
                        Notification.update({
                            id,
                            message,
                            type: "error",
                            ...options
                        });
                    } else {
                        Notification.error(message, options);
                    }
                } else {
                    if (id) {
                        Notification.dismiss(id);
                    }
                }
            }
        }
    });

    commands.addCommand(CommandIDs.gitPull, {
        label: args => (args.force ? trans.__("Pull from Remote (Force)") : trans.__("Pull from Remote")),
        caption: args => args.force ? trans.__("Discard all current changes and pull from remote repository") : trans.__("Pull latest code from remote repository"),
        isEnabled: () => gitModel.pathRepository !== null,

        execute: async args => {
            let id: string | null = null;

            try {
                if (args.force) {
                    await discardAllChanges(gitModel, trans, args.fallback as boolean);
                }

                id = Notification.emit(trans.__("Pulling…"), "in-progress", {
                    autoClose: false
                });

                const details = await showGitOperationDialog(gitModel, Operation.Pull, trans);

                Notification.update({
                    id,
                    message: trans.__("Successfully pulled"),
                    type: "success",
                    ...showDetails(details, trans)
                });
            } catch (error: any) {
                if (error.name !== "CancelledError") {
                    console.error("Encountered an error when pulling changes. Error: ", error);
                    const errorMsg = typeof error === "string" ? error : (error as Error).message;

                    if (errorMsg.toLowerCase().includes("your local changes to the following files would be overwritten by merge")) {
                        await commands.execute(CommandIDs.gitPull, {
                            force: true,
                            fallback: true
                        });
                    } else {
                        if ((error as any).cancelled) {
                            if (id) {
                                Notification.dismiss(id);
                            }
                        } else {
                            const message = trans.__("Failed to pull");
                            const options = showError(error, trans);

                            if (id) {
                                Notification.update({
                                    id,
                                    message,
                                    ...options
                                });
                            } else {
                                Notification.error(message, options);
                            }
                        }
                    }
                } else {
                    if (id) {
                        Notification.dismiss(id);
                    }
                }
            }
        }
    });

    commands.addCommand(CommandIDs.gitResetToRemote, {
        label: trans.__("Reset to Remote"),
        caption: trans.__("Reset Current Branch to Remote State"),
        isEnabled: () => gitModel.pathRepository !== null,

        execute: async () => {
            const result = await showDialog({
                title: trans.__("Reset to Remote"),

                body: new CheckboxForm(trans.__(
                    "To bring the current branch to the state of its corresponding remote tracking branch,             a hard reset will be performed, which may result in some files being permanently deleted             and some changes being permanently discarded. Are you sure you want to proceed?             This action cannot be undone."
                ), trans.__("Close all opened files to avoid conflicts")),

                buttons: [Dialog.cancelButton({
                    label: trans.__("Cancel")
                }), Dialog.warnButton({
                    label: trans.__("Proceed")
                })]
            });

            if (result.button.accept) {
                let id: string | null = null;

                try {
                    if (result.value?.checked) {
                        id = Notification.emit(trans.__("Closing all opened files..."), "in-progress");
                        await fileBrowserModel.manager.closeAll();
                    }

                    const message = trans.__("Resetting...");

                    if (id) {
                        Notification.update({
                            id,
                            message
                        });
                    } else {
                        id = Notification.emit(message, "in-progress", {
                            autoClose: false
                        });
                    }

                    await gitModel.resetToCommit(gitModel.status.remote ?? undefined);

                    Notification.update({
                        id,
                        message: trans.__("Successfully reset"),
                        type: "success",

                        ...showDetails(
                            trans.__("Successfully reset the current branch to its remote state"),
                            trans
                        )
                    });
                } catch (error) {
                    console.error(
                        "Encountered an error when resetting the current branch to its remote state. Error: ",
                        error
                    );

                    const message = trans.__("Reset failed");
                    const options = showError(error as Error, trans);

                    if (id) {
                        Notification.update({
                            id,
                            type: "error",
                            message,
                            ...options
                        });
                    } else {
                        Notification.error(message, options);
                    }
                }
            }
        }
    });

    commands.addCommand(CommandIDs.gitShowDiff, {
        label: trans.__("Show Diff"),
        caption: trans.__("Display a file diff."),

        execute: async args => {
            const {
                model,
                isText,
                isPreview
            } = args as any as {
                model: Git.Diff.IModel;
                isText?: boolean;
                isPreview?: boolean;
            };

            const fullPath = PathExt.join(model.repositoryPath ?? "/", model.filename);

            const buildDiffWidget = getDiffProvider(fullPath) ?? (isText && (options => createPlainTextDiff({
                ...options,
                editorFactory: editorFactory.newInlineEditor.bind(editorFactory),
                languageRegistry
            })));

            if (buildDiffWidget) {
                const id = `git-diff-${fullPath}-${model.reference.label}-${model.challenger.label}`;
                const mainAreaItems = shell.widgets("main");
                let mainAreaItem: Widget | null = null;

                for (const item of mainAreaItems) {
                    if (item.id === id) {
                        shell.activateById(id);
                        mainAreaItem = item;
                        break;
                    }
                }

                if (!mainAreaItem) {
                    const content = new Panel();
                    const modelIsLoading = new PromiseDelegate<void>();

                    const diffWidget = (mainAreaItem = new PreviewMainAreaWidget<Panel>({
                        content,
                        reveal: modelIsLoading.promise,
                        isPreview
                    }));

                    diffWidget.id = id;
                    diffWidget.title.label = PathExt.basename(model.filename);
                    diffWidget.title.caption = fullPath;
                    diffWidget.title.icon = diffIcon;
                    diffWidget.title.closable = true;
                    diffWidget.title.className = "jp-git-diff-title";
                    diffWidget.addClass("jp-git-diff-parent-widget");
                    shell.add(diffWidget, "main");
                    shell.activateById(diffWidget.id);
                    const dockPanel = (app.shell as any)._dockPanel as DockPanel;
                    let tabPosition = -1;

                    const tabBar = Array.from(dockPanel.tabBars()).find(bar => {
                        tabPosition = bar.titles.indexOf(diffWidget.title);
                        return tabPosition !== -1;
                    });

                    if (tabBar) {
                        PreviewMainAreaWidget.pinWidget(tabPosition, tabBar, diffWidget);
                    }

                    try {
                        const widget = await buildDiffWidget({
                            model,
                            toolbar: diffWidget.toolbar,
                            translator
                        });

                        diffWidget.toolbar.addItem("spacer", Toolbar.createSpacerItem());

                        if (model.hasConflict) {
                            const resolveButton = new ToolbarButton({
                                label: trans.__("Mark as resolved"),

                                onClick: async () => {
                                    if (!widget.isFileResolved) {
                                        const result = await showDialog({
                                            title: trans.__("Resolve with conflicts"),

                                            body: trans.__(
                                                "Are you sure you want to mark this file as resolved with merge conflicts?"
                                            )
                                        });

                                        if (!result.button.accept) {
                                            return;
                                        }
                                    }

                                    try {
                                        await serviceManager.contents.save(fullPath, await widget.getResolvedFile());
                                        await gitModel.add(model.filename);
                                        await gitModel.refresh();
                                    } catch (reason) {
                                        Notification.error((reason as Error).message ?? (reason as string));
                                    } finally {
                                        diffWidget.dispose();
                                    }
                                },

                                tooltip: trans.__("Mark file as resolved"),
                                className: "jp-git-diff-resolve"
                            });

                            diffWidget.toolbar.addItem("resolve", resolveButton);
                        } else {
                            const refreshButton = new ToolbarButton({
                                label: trans.__("Refresh"),

                                onClick: async () => {
                                    await widget.refresh();
                                    refreshButton.hide();
                                },

                                tooltip: trans.__("Refresh diff widget"),
                                className: "jp-git-diff-refresh"
                            });

                            refreshButton.hide();
                            diffWidget.toolbar.addItem("refresh", refreshButton);

                            const refresh = () => {
                                refreshButton.show();
                            };

                            model.changed.connect(refresh);
                            widget.disposed.connect(() => model.changed.disconnect(refresh));
                        }

                        modelIsLoading.resolve();
                        content.addWidget(widget);
                    } catch (reason) {
                        console.error(reason);
                        const msg = `Load Diff Model Error (${(reason as Error).message || reason})`;
                        modelIsLoading.reject(msg);
                    }

                    if (model.challenger.source === Git.Diff.SpecialRef.INDEX || model.challenger.source === Git.Diff.SpecialRef.WORKING || model.reference.source === Git.Diff.SpecialRef.INDEX || model.reference.source === Git.Diff.SpecialRef.WORKING) {
                        const maybeClose = (_: IGitExtension, status: Git.IStatus) => {
                            const targetFile = status.files.find(fileStatus => model.filename === fileStatus.from);

                            if (!targetFile || targetFile.status === "unmodified") {
                                gitModel.statusChanged.disconnect(maybeClose);
                                mainAreaItem!.dispose();
                            }
                        };

                        gitModel.statusChanged.connect(maybeClose);
                    }
                }

                return mainAreaItem;
            } else {
                await showErrorMessage(trans.__("Diff Not Supported"), trans.__(
                    "Diff is not supported for %1 files.",
                    PathExt.extname(model.filename).toLocaleLowerCase()
                ));

                return null;
            }
        },

        icon: diffIcon.bindprops({
            stylesheet: "menuItem"
        })
    });

    commands.addCommand(CommandIDs.gitMerge, {
        label: trans.__("Merge Branch…"),
        caption: trans.__("Merge selected branch in the current branch"),

        execute: async args => {
            let {
                branch
            }: {
                branch?: string;
            } = args ?? {};

            if (!branch) {
                const localBranches = gitModel.branches.filter(branch => !branch.is_current_branch && !branch.is_remote_branch);
                const widgetId = "git-dialog-MergeBranch";
                let anchor = document.querySelector<HTMLDivElement>(`#${widgetId}`);

                if (!anchor) {
                    anchor = document.createElement("div");
                    anchor.id = widgetId;
                    document.body.appendChild(anchor);
                }

                const waitForDialog = new PromiseDelegate<string | null>();

                const dialog = ReactWidget.create(<BranchPicker
                    action="merge"
                    currentBranch={gitModel.currentBranch?.name ?? ""}
                    branches={localBranches}
                    onClose={(branch?: string) => {
                        dialog.dispose();
                        waitForDialog.resolve(branch ?? null);
                    }}
                    trans={trans} />);

                Widget.attach(dialog, anchor);
                branch = (await waitForDialog.promise) ?? undefined;
            }

            if (branch) {
                const id = Notification.emit(trans.__("Merging branch '%1'…", branch), "in-progress");

                try {
                    await gitModel.merge(branch);
                } catch (err) {
                    Notification.update({
                        id,
                        type: "error",

                        message: trans.__(
                            "Failed to merge branch '%1' into '%2'.",
                            branch,
                            gitModel.currentBranch?.name
                        ),

                        ...showError(err as Error, trans)
                    });

                    return;
                }

                Notification.update({
                    id,
                    type: "success",
                    message: trans.__("Branch '%1' merged into '%2'.", branch, gitModel.currentBranch?.name)
                });
            }
        },

        isEnabled: () => gitModel.branches.some(branch => !branch.is_current_branch && !branch.is_remote_branch)
    });

    commands.addCommand(CommandIDs.gitRebase, {
        label: trans.__("Rebase branch…"),
        caption: trans.__("Rebase current branch onto the selected branch"),

        execute: async args => {
            let {
                branch
            }: {
                branch?: string;
            } = args ?? {};

            if (!branch) {
                const localBranches = gitModel.branches.filter(branch => !branch.is_current_branch && !branch.is_remote_branch);
                const widgetId = "git-dialog-MergeBranch";
                let anchor = document.querySelector<HTMLDivElement>(`#${widgetId}`);

                if (!anchor) {
                    anchor = document.createElement("div");
                    anchor.id = widgetId;
                    document.body.appendChild(anchor);
                }

                const waitForDialog = new PromiseDelegate<string | null>();

                const dialog = ReactWidget.create(<BranchPicker
                    action="rebase"
                    currentBranch={gitModel.currentBranch?.name ?? ""}
                    branches={localBranches}
                    onClose={(branch?: string) => {
                        dialog.dispose();
                        waitForDialog.resolve(branch ?? null);
                    }}
                    trans={trans} />);

                Widget.attach(dialog, anchor);
                branch = (await waitForDialog.promise) ?? undefined;
            }

            if (branch) {
                const id = Notification.emit(trans.__("Rebasing current branch onto '%1'…", branch), "in-progress");

                try {
                    await gitModel.rebase(branch);
                } catch (err) {
                    Notification.update({
                        id,
                        type: "error",

                        message: trans.__(
                            "Failed to rebase branch '%1' onto '%2'.",
                            gitModel.currentBranch?.name,
                            branch
                        ),

                        ...showError(err as Error, trans)
                    });

                    return;
                }

                Notification.update({
                    id,
                    type: "success",
                    message: trans.__("Branch '%1' rebase onto '%2'.", gitModel.currentBranch?.name, branch)
                });
            }
        },

        isEnabled: () => gitModel.branches.some(branch => !branch.is_current_branch && !branch.is_remote_branch)
    });

    commands.addCommand(CommandIDs.gitResolveRebase, {
        label: (args = {}) => {
            switch (args.action) {
            case "continue":
                return trans.__("Continue rebase");
            case "skip":
                return trans.__("Skip current commit");
            case "abort":
                return trans.__("Abort rebase");
            default:
                return trans.__("Resolve rebase");
            }
        },

        caption: (args = {}) => {
            switch (args.action) {
            case "continue":
                return trans.__("Continue the rebase by committing the current state.");
            case "skip":
                return trans.__("Skip current commit and continue the rebase.");
            case "abort":
                return trans.__("Abort the rebase");
            default:
                return trans.__("Resolve rebase");
            }
        },

        execute: async (
            args: {
                action?: string;
            } = {}
        ) => {
            const {
                action
            } = args;

            if (["continue", "abort", "skip"].includes(action ?? "")) {
                const message = (action => {
                    switch (action) {
                    case "continue":
                        return trans.__("Continue the rebase…");
                    case "skip":
                        return trans.__("Skip current commit…");
                    case "abort":
                        return trans.__("Abort the rebase…");
                    }
                })(action) ?? "";

                const id = Notification.emit(message, "in-progress", {
                    autoClose: false
                });

                try {
                    await gitModel.resolveRebase(action as any);
                } catch (err) {
                    const message = (action => {
                        switch (action) {
                        case "continue":
                            return trans.__("Fail to continue rebasing.");
                        case "skip":
                            return trans.__("Fail to skip current commit when rebasing.");
                        case "abort":
                            return trans.__("Fail to abort the rebase.");
                        }
                    })(action) ?? "";

                    Notification.update({
                        id,
                        type: "error",
                        message,
                        ...showError(err as Error, trans)
                    });

                    return;
                }

                const message_ = (action => {
                    switch (action) {
                    case "continue":
                        return trans.__("Commit submitted continuing rebase.");
                    case "skip":
                        return trans.__("Current commit skipped.");
                    case "abort":
                        return trans.__("Rebase aborted.");
                    }
                })(action) ?? "";

                Notification.update({
                    id,
                    type: "success",
                    message: message_,
                    autoClose: 5000
                });
            }
        },

        isEnabled: () => gitModel.status.state === Git.State.REBASING
    });

