    commands.addCommand(ContextCommandIDs.gitFileDiff, {
        label: trans.__("Diff"),
        caption: pluralizedContextLabel(trans.__("Diff selected file"), trans.__("Diff selected files")),

        execute: async args => {
            const {
                files
            } = args as any as CommandArguments.IGitFileDiff;

            if (gitModel.pathRepository === null) {
                return;
            }

            for (const file of files) {
                const {
                    context,
                    filePath,
                    previousFilePath,
                    isText,
                    status,
                    isPreview
                } = file;

                if (status === "untracked") {
                    continue;
                }

                const repositoryPath = gitModel.pathRepository;
                const filename = filePath;
                const fullPath = PathExt.join(repositoryPath, filename);

                const diffContext: Git.Diff.IContext = {
                    currentRef: "",
                    previousRef: "HEAD",
                    ...context
                };

                if (status === "unmerged") {
                    diffContext.baseRef = Git.Diff.SpecialRef.BASE;
                    diffContext.currentRef = gitModel.status.state !== Git.State.MERGING ? gitModel.status.state === Git.State.REBASING ? "REBASE_HEAD" : "CHERRY_PICK_HEAD" : "MERGE_HEAD";
                } else if (!diffContext.currentRef) {
                    diffContext.currentRef = status === "staged" ? Git.Diff.SpecialRef.INDEX : Git.Diff.SpecialRef.WORKING;
                }

                const challengerRef = Git.Diff.SpecialRef[diffContext.currentRef as any] ? {
                    special: Git.Diff.SpecialRef[diffContext.currentRef as any]
                } : {
                    git: diffContext.currentRef
                };

                const props: Omit<Git.Diff.IModel, "changed" | "hasConflict"> = {
                    challenger: {
                        content: async () => {
                            return requestAPI<Git.IDiffContent>(URLExt.join(repositoryPath, "content"), "POST", {
                                filename,
                                reference: challengerRef
                            }).then(data => data.content);
                        },

                        label: (Git.Diff.SpecialRef[diffContext.currentRef as any] as any) || diffContext.currentRef,
                        source: diffContext.currentRef,
                        updateAt: Date.now()
                    },

                    filename,

                    reference: {
                        content: async () => {
                            return requestAPI<Git.IDiffContent>(URLExt.join(repositoryPath, "content"), "POST", {
                                filename: previousFilePath ?? filename,

                                reference: {
                                    git: diffContext.previousRef
                                }
                            }).then(data => data.content);
                        },

                        label: (Git.Diff.SpecialRef[diffContext.previousRef as any] as any) || diffContext.previousRef,
                        source: diffContext.previousRef,
                        updateAt: Date.now()
                    },

                    repositoryPath
                };

                if (previousFilePath) {
                    props.reference.label = `${previousFilePath} (${props.reference.label.slice(0, 7)})`;
                    props.challenger.label = `${filePath} (${props.challenger.label.slice(0, 7)})`;
                }

                if (diffContext.baseRef) {
                    props.reference.label = trans.__("Current");
                    props.challenger.label = trans.__("Incoming");

                    props.base = {
                        content: async () => {
                            return requestAPI<Git.IDiffContent>(URLExt.join(repositoryPath, "content"), "POST", {
                                filename,

                                reference: {
                                    special: Git.Diff.SpecialRef[diffContext.baseRef as any]
                                }
                            }).then(data => data.content);
                        },

                        label: trans.__("Result"),
                        source: diffContext.baseRef,
                        updateAt: Date.now()
                    };
                }

                const model = new DiffModel(props);

                const widget = await commands.execute(CommandIDs.gitShowDiff, {
                    model,
                    isText,
                    isPreview
                } as any);

                if (widget) {
                    if (diffContext.previousRef === "HEAD") {
                        const updateHead = () => {
                            model.reference = {
                                ...model.reference,
                                updateAt: Date.now()
                            };
                        };

                        gitModel.headChanged.connect(updateHead);

                        widget.disposed.connect(() => {
                            gitModel.headChanged.disconnect(updateHead);
                        });
                    }

                    if (diffContext.currentRef === Git.Diff.SpecialRef.WORKING) {
                        const updateCurrent = (m: Contents.IManager, change: Contents.IChangedArgs) => {
                            const updateAt = new Date(change.newValue?.last_modified ?? 0).valueOf();

                            if (app.serviceManager.contents.localPath(change.newValue?.path ?? "") === fullPath && model.challenger.updateAt !== updateAt) {
                                model.challenger = {
                                    ...model.challenger,
                                    updateAt
                                };
                            }
                        };

                        app.serviceManager.contents.fileChanged.connect(updateCurrent);

                        widget.disposed.connect(() => {
                            app.serviceManager.contents.fileChanged.disconnect(updateCurrent);
                        });
                    }
                }
            }
        },

        icon: diffIcon.bindprops({
            stylesheet: "menuItem"
        })
    });

