                return reject(error);
            }

            try {
                const screenshotData = await fs.readFile(screenshotPath);

                console.log(
                    `[DIRECT-SCREENSHOT] Read ${screenshotData.length} bytes from screenshot file`
                );

                const base64Data = screenshotData.toString("base64");

                await fs.unlink(screenshotPath).catch(
                    err => console.warn(`[DIRECT-SCREENSHOT] Failed to delete temp file: ${err.message}`)
                );

                resolve(base64Data);
