async function localFileFromUrl(url: string): Promise<string> {
    const cssPluginAssets = "css/pluginAssets/";
    const jsPluginAssets = "js/pluginAssets/";

    if (url.indexOf(cssPluginAssets) === 0)
        return `${pluginAssetRootDir_}/${url.substr(cssPluginAssets.length)}`;

    if (url.indexOf(jsPluginAssets) === 0)
        return `${pluginAssetRootDir_}/${url.substr(jsPluginAssets.length)}`;

    return null;
}

async function localFileFromUrl(urlPath: string): Promise<string> {
    const cssPluginAssets = "css/pluginAssets/";
    const jsPluginAssets = "js/pluginAssets/";
    const baseUrls = [cssPluginAssets, jsPluginAssets];

    for (const baseUrl of baseUrls) {
        if (urlPath.startsWith(baseUrl)) {
            const pluginAssetPath = urlPath.substring(baseUrl.length);
            return resolveUnsafeAssetPath(pluginAssetPath);
        }
    }

    return null;
}

